// ifNameRE matches the enforce interface rule (AGENTS.md §4).
var ifNameRE = regexp.MustCompile(`^fv[a-z0-9_-]{1,13}$`)

var releaseRE = regexp.MustCompile(`^[0-9A-Za-z][0-9A-Za-z.+_-]{0,63}$`)

// Config is /etc/vpn-node/agent.json. It holds paths and ids, never a token,
// a private key or a setup key.
type Config struct {
	StateDir                string         `json:"state_dir"`
	MeterCheckpoint         string         `json:"meter_checkpoint,omitempty"`
	CurrentReleasePath      string         `json:"current_release_path,omitempty"`
	IdentityDir             string         `json:"identity_dir"`
	JournalDir              string         `json:"journal_dir"`
	LockPath                string         `json:"lock_path"`
	ControlURL              string         `json:"control_url"`
	ServerCAFile            string         `json:"server_ca_file"`
	TrustBundle             string         `json:"trust_bundle"`
	DesiredStatePath        string         `json:"desired_state_path"`
	HeartbeatPath           string         `json:"heartbeat_path"`
	Datapath                DatapathConfig `json:"datapath"`
	AgentRelease            string         `json:"agent_release"`
	ReleaseID               string         `json:"release_id"`
	RenewLeadSeconds        int            `json:"renew_lead_seconds"`
	HeartbeatSeconds        int            `json:"heartbeat_seconds"`
	WatchdogStaleSeconds    int            `json:"watchdog_stale_seconds"`
	WatchdogIntervalSeconds int            `json:"watchdog_interval_seconds"`
	PollSeconds             int            `json:"poll_seconds"`
	ObservationSeconds      int            `json:"observation_seconds"`
	TestMode                bool           `json:"test_mode"`
	// TestTimingPath appends local diagnostic JSONL after each operation.
	// TEST ONLY: no HTTP field, disabled by default; the harness owns retention.
	TestTimingPath string   `json:"test_timing_path,omitempty"`
	TestExemptV4   []string `json:"test_exempt_v4"`
	ExtraDeniedV4  []string `json:"extra_denied_v4"`
	HostV4         []string `json:"host_v4"`
	HostReserveBPS uint64   `json:"host_reserve_bps"`
	NetbirdBackend string   `json:"netbird_backend"`
	// NetbirdStatusFile, when set, is a NetBird `status --json` document
	// the probe reads instead of running the CLI. Production leaves this
	// empty. The lab container has no NetBird daemon and points it at a
	// fixture. It is not a way to mark the probe passed by itself: the
	// JSON still has to say management is connected.
	NetbirdStatusFile string `json:"netbird_status_file"`
	// EgressProbeTarget is host:port for the data-path probe. Empty skips
	// that leg. A non-null signed egress_probe replaces it (D-058).
	EgressProbeTarget string `json:"egress_probe_target"`
	UpdaterRecover    string `json:"updater_recover"`
	UpdaterConfig     string `json:"updater_config"`
	// UpdaterJournal is the updater journal database file (journal.db).
	// JournalDir is that file's directory and stays the location of the
	// health sidecars and the forwarding latch. Empty selects the updater
	// default, /var/lib/vpn-node/update-journal/journal.db.
	UpdaterJournal string `json:"updater_journal"`
	BootIDFile     string `json:"boot_id_file"`
	// DNS is optional. Absent keeps the resolver applier unset (D-061).
	DNS *DNSConfig `json:"dns,omitempty"`
}

// DatapathConfig names the interfaces enforce binds to.
type DatapathConfig struct {
	MemberIngress string `json:"member_ingress"`
	Uplink        string `json:"uplink"`
	SNAT          string `json:"snat"`
}

// LoadConfig reads agent.json. Unknown fields are rejected. Zero durations
// take the defaults from §16.3 and §16.5.
func LoadConfig(path string) (Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return Config{}, err
	}
	dec := json.NewDecoder(bytesReader(b))
	dec.DisallowUnknownFields()
	var c Config
	if err := dec.Decode(&c); err != nil {
		return Config{}, fmt.Errorf("agent: config: %w", err)
	}
	c.applyDefaults()
	if err := c.validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

func (c *Config) applyDefaults() {
	if c.StateDir == "" {
		c.StateDir = "/var/lib/vpn-node/state"
	}
	if c.MeterCheckpoint == "" {
		c.MeterCheckpoint = filepath.Join(c.StateDir, "meter.checkpoint")
	}
	if c.CurrentReleasePath == "" {
		c.CurrentReleasePath = "/opt/vpn-node/current"
	}
	if c.IdentityDir == "" {
		c.IdentityDir = "/var/lib/vpn-node/identity"
	}
	if c.JournalDir == "" {
		c.JournalDir = updatejournal.DefaultDir
	}
	if c.UpdaterJournal == "" {
		c.UpdaterJournal = filepath.Join(updatejournal.DefaultDir, updatejournal.FileName)
	}
	if c.LockPath == "" {
		c.LockPath = "/var/lib/vpn-node/update.lock"
	}
	if c.DesiredStatePath == "" {
		c.DesiredStatePath = filepath.Join(c.StateDir, "desired-state.json")
	}
	if c.HeartbeatPath == "" {
		c.HeartbeatPath = "/run/vpn-node/heartbeat"
	}
	if c.RenewLeadSeconds <= 0 {
		c.RenewLeadSeconds = 120
	}
	if c.HeartbeatSeconds <= 0 {
		c.HeartbeatSeconds = 10
	}
	if c.WatchdogStaleSeconds <= 0 {
		c.WatchdogStaleSeconds = 30
	}
	if c.PollSeconds <= 0 {
		c.PollSeconds = 10
	}
	if c.ObservationSeconds <= 0 {
		c.ObservationSeconds = 30
	}
	if c.NetbirdBackend == "" {
		c.NetbirdBackend = "unknown"
	}
}

// ErrHostReserve means host_reserve_bps is missing or zero. The process
// exits with ExitUsage before it touches the kernel or the network (D-034).
var ErrHostReserve = errors.New("agent: host_reserve_bps is required and must be greater than zero")

// ExitUsage is the usage-error status (64, D-034). fvpn-agent returns it
// for ErrHostReserve. The updater process is not modified here.
const ExitUsage = 64

// ExitStatus maps a startup error to a process status. ErrHostReserve is
// ExitUsage. Every other error is 1. A nil error is 0.
func ExitStatus(err error) int {
	if err == nil {
		return 0
	}
	if errors.Is(err, ErrHostReserve) {
		return ExitUsage
	}
	return 1
}

func (c Config) validate() error {
	if c.TestTimingPath != "" && (!c.TestMode || !filepath.IsAbs(c.TestTimingPath)) {
		return errors.New("agent: test_timing_path requires test_mode and an absolute path")
	}
	if c.HostReserveBPS == 0 {
		return ErrHostReserve
	}
	if c.ControlURL == "" || c.ServerCAFile == "" || c.TrustBundle == "" {
		return errors.New("agent: control URL, CA and trust bundle are required")
	}
	if c.AgentRelease == "" || c.AgentRelease == "latest" || !releaseRE.MatchString(c.AgentRelease) {
		return errors.New("agent: agent_release must be a pinned version")
	}
	if c.ReleaseID != "" {
		if _, err := uuid.Parse(c.ReleaseID); err != nil {
			return errors.New("agent: release_id is not a UUID")
		}
	}
	if !c.TestMode && len(c.TestExemptV4) > 0 {
		return errors.New("agent: test_exempt_v4 requires test_mode")
	}
	if _, err := c.DatapathValue(); err != nil {
		return err
	}
	if _, err := parsePrefixes(c.TestExemptV4); err != nil {
		return err
	}
	if _, err := parsePrefixes(c.ExtraDeniedV4); err != nil {
		return err
	}
	if _, err := parsePrefixes(c.HostV4); err != nil {
		return err
	}
	switch c.NetbirdBackend {
	case "kernel", "userspace", "unknown":
	default:
		return errors.New("agent: netbird_backend must be kernel, userspace or unknown")
	}
	if c.EgressProbeTarget != "" {
		if _, _, err := net.SplitHostPort(c.EgressProbeTarget); err != nil {
			return errors.New("agent: egress_probe_target must be host:port")
		}
	}
	if err := c.validateDNS(); err != nil {
		return err
	}
	if err := c.validateUpdaterJournal(); err != nil {
		return err
	}
	return nil
}

// errUpdaterJournal is a fixed load error. It does not include the path.
var errUpdaterJournal = errors.New("agent: updater_journal is not usable")

func (c Config) validateUpdaterJournal() error {
	p := c.UpdaterJournal
	if p == "" || len(p) > 4096 || strings.ContainsRune(p, 0) || strings.Contains(p, "://") || !filepath.IsAbs(p) {
		return errUpdaterJournal
	}
	return nil
}

// DBPath is the agent SQLite file.
func (c Config) DBPath() string { return filepath.Join(c.StateDir, "agent.db") }

// UsageDBPath is the usage ledger. It is a different file from the agent store.
func (c Config) UsageDBPath() string { return filepath.Join(c.StateDir, "usage.db") }

// DatapathValue parses the datapath section.
func (c Config) DatapathValue() (enforce.Datapath, error) {
	if !ifNameRE.MatchString(c.Datapath.MemberIngress) || !ifNameRE.MatchString(c.Datapath.Uplink) {
		return enforce.Datapath{}, errors.New("agent: datapath interface names must start with fv")
	}
	if c.Datapath.MemberIngress == c.Datapath.Uplink {
		return enforce.Datapath{}, errors.New("agent: member ingress and uplink must differ")
	}
	snat, err := netip.ParseAddr(c.Datapath.SNAT)
	if err != nil || !snat.Is4() {
		return enforce.Datapath{}, errors.New("agent: snat must be an IPv4 address")
	}
	return enforce.Datapath{MemberIngress: c.Datapath.MemberIngress, Uplink: c.Datapath.Uplink, SNAT: snat}, nil
}

// ReleaseUUID parses release_id. The nil UUID means the local release is unknown.
func (c Config) ReleaseUUID() uuid.UUID {
	id, err := uuid.Parse(c.ReleaseID)
	if err != nil {
		return uuid.Nil
	}
	return id
}

func parsePrefixes(in []string) ([]netip.Prefix, error) {
	out := make([]netip.Prefix, 0, len(in))
	for _, s := range in {
		p, err := netip.ParsePrefix(s)
		if err != nil {
			return nil, fmt.Errorf("agent: prefix %q", s)
		}
		out = append(out, p)
	}
	return out, nil
}

type sliceReader struct {
	b []byte
	i int
}

func bytesReader(b []byte) *sliceReader { return &sliceReader{b: b} }

func (s *sliceReader) Read(p []byte) (int, error) {
	if s.i >= len(s.b) {
		return 0, io.EOF
	}
	n := copy(p, s.b[s.i:])
	s.i += n
	return n, nil
}

package agent

import (
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/google/uuid"
)

// D-157 is one opportunity per verified closed Apply, not per empty lease or
// report. It is process-local: restart does not recreate a closed Apply receipt.
type recoveryRenewal struct {
	armed    bool
	reportID uuid.UUID
	accepted bool
}

func (e *Engine) recoveryRenewalEligible() bool {
	return e.closedRecoveryHeld && !e.serving && e.applyError == nil &&
		!e.revoked && !e.identityFrozen && !e.freezeUncertain && e.storageOK &&
		!e.quarantinePending && !e.memberPathPending && !e.dependencyMissing &&
		e.appliedGen > 0 && e.desiredOK && !e.desiredExpired && e.desired != nil &&
		uint64(e.desired.ConfigGeneration) == e.appliedGen && e.leaseGrantless() &&
		!e.leaseBehindApplied()
}

// Bind to a newly queued report from this recovery. An old queued report, even
// at the same generation, cannot arm a later recovery's opportunity.
func (e *Engine) noteRecoveryReport(rep api.ObservationReport) {
	r := &e.closedRecoveryRenewal
	if !r.armed || r.reportID != uuid.Nil || !e.recoveryRenewalEligible() {
		return
	}
	gen, err := rep.AppliedConfigGeneration.Get()
	if err != nil || uint64(gen) != e.appliedGen || rep.MemberForwardingEnabled ||
		rep.SafetyStatus != api.SafetyStatusPassed || rep.ProvisioningState != api.ProvisioningStateReady ||
		rep.Netbird.Backend != api.ObservationReportNetbirdBackendKernel || !rep.Netbird.PeerId.IsNull() {
		return
	}
	// These are central's synchronous readiness evidence requirements. A failed
	// meter path is never the D-067 awaiting-grants exception.
	internet, awaiting := false, false
	for _, reason := range rep.ForwardingBlockReasons {
		awaiting = awaiting || reason == api.ForwardingBlockReasonAwaitingMemberGrants
	}
	for _, check := range rep.Checks {
		if check.Name == api.NodeCheckNameInternetOnly {
			internet = check.Status == api.HealthCheckStatusPassed
		}
		if check.Name == api.NodeCheckNameMeterPath && check.Status == api.HealthCheckStatusFailed {
			return
		}
	}
	for _, err := range rep.Errors {
		switch err.Code {
		case api.ErrorCodeISOLATIONPOLICYINVALID, api.ErrorCodeISOLATIONBASELINEMISSING, api.ErrorCodeMETERPATHINVALID:
			return
		}
	}
	if internet && awaiting {
		r.reportID = rep.ReportId
	}
}

func (e *Engine) acceptRecoveryReport(rep api.ObservationReport, accepted api.ObservationAccepted) {
	r := &e.closedRecoveryRenewal
	if r.armed && r.reportID != uuid.Nil && rep.ReportId == r.reportID &&
		accepted.ReportId == rep.ReportId && bool(accepted.Accepted) &&
		(accepted.IdentityFrozen == nil || !*accepted.IdentityFrozen) && e.recoveryRenewalEligible() {
		r.accepted = true
	}
}

func (e *Engine) earlyRecoveryRenewal() bool {
	return e.closedRecoveryRenewal.armed && e.closedRecoveryRenewal.accepted && e.recoveryRenewalEligible()
}

// Command fvpn-agent is the exit-node agent (§5, §16.3).
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"github.com/TED-H-com/Freedom-VPN/node/agent"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	switch os.Args[1] {
	case "enroll":
		os.Exit(enroll(os.Args[2:]))
	case "run":
		os.Exit(run(os.Args[2:], true))
	case "step":
		os.Exit(run(os.Args[2:], false))
	case "version":
		fmt.Println("fvpn-agent dev")
	case "usage":
		os.Exit(usageCommand(os.Args[2:]))
	default:
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: fvpn-agent enroll -config path -token-file path|-")
	fmt.Fprintln(os.Stderr, "       fvpn-agent run|step -config path")
	fmt.Fprintln(os.Stderr, "       fvpn-agent usage snapshot -config path [-json]")
	fmt.Fprintln(os.Stderr, "       fvpn-agent version")
}

func enroll(args []string) int {
	fs := flag.NewFlagSet("enroll", flag.ContinueOnError)
	config := fs.String("config", "", "path to agent.json")
	tokenFile := fs.String("token-file", "", "enrollment token file, or - for stdin")
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 || *config == "" || *tokenFile == "" {
		usage()
		return 2
	}
	// The token is read from the file or stdin only. The environment is ignored (§6.1).
	token, err := agent.ReadToken(*tokenFile)
	if err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: token file")
		return 1
	}
	eng, err := open(*config)
	if err != nil {
		if agent.ExitStatus(err) == agent.ExitUsage {
			fmt.Fprintln(os.Stderr, "fvpn-agent: configuration error: host_reserve_bps is required and must be greater than zero")
			return agent.ExitUsage
		}
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	defer eng.Close()
	if err := eng.Enroll(context.Background(), token); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: enrollment failed")
		return 1
	}
	if err := agent.NeutralizeToken(*tokenFile); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent: token file")
		return 1
	}
	return 0
}

type runEngine interface {
	Run(context.Context) error
	Boot(context.Context) error
	Step(context.Context) error
	Close() error
}

func run(args []string, loop bool) int {
	return runWithOpen(args, loop, func(path string) (runEngine, error) { return open(path) })
}

func runWithOpen(args []string, loop bool, open func(string) (runEngine, error)) int {
	// Cover startup too, and retain signal handling until Close has completed.
	// Supervisors may send another TERM while the local checkpoint is running.
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()
	fs := flag.NewFlagSet("run", flag.ContinueOnError)
	config := fs.String("config", "", "path to agent.json")
	fs.SetOutput(os.Stderr)
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 || *config == "" {
		usage()
		return 2
	}
	eng, err := open(*config)
	if err != nil {
		if agent.ExitStatus(err) == agent.ExitUsage {
			fmt.Fprintln(os.Stderr, "fvpn-agent: configuration error: host_reserve_bps is required and must be greater than zero")
			return agent.ExitUsage
		}
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	defer eng.Close()
	if loop {
		if err := eng.Run(ctx); err != nil && (errors.Is(err, agent.ErrBoot) || ctx.Err() == nil || !errors.Is(err, ctx.Err())) {
			fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
			return 1
		}
		return 0
	}
	if err := eng.Boot(ctx); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	if err := eng.Step(ctx); err != nil {
		fmt.Fprintln(os.Stderr, "fvpn-agent:", err.Error())
		return 1
	}
	return 0
}

func open(path string) (*agent.Engine, error) {
	cfg, err := agent.LoadConfig(path)
	if err != nil {
		return nil, err
	}
	log := slog.New(agent.RedactHandler{Next: slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: slog.LevelInfo})})
	return agent.Start(agent.Options{Config: cfg, Log: log})
}

package updater

import (
	"context"
	"errors"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/nodelock"
)

// D-158 is a contention policy, not a maximum holder lifetime. It applies to
// run, seed, apply and standalone flush, which can overlap a serving agent.
const updateLockWaitBudget = 10 * time.Second

const lockRetryInterval = 20 * time.Millisecond
const promptLockAttempts = 5

// acquireCommandLock leaves the common lock APIs and their consumers unchanged.
// Five consecutive stale answers, 20 ms apart, return the final stale detail.
// A live answer (including empty/unreadable metadata) resets that count and
// obeys the 10 s budget from the first attempt: only a live answer at/past the
// deadline ends live contention. Stale retries can extend it by about 100 ms,
// plus filesystem/scheduling time. Log once only if the first attempt is busy.
func (e *Engine) acquireCommandLock(ctx context.Context, command string) (lk *nodelock.Lock, err error) {
	started := time.Now()
	waited := false
	defer func() {
		if waited {
			e.log().Info("update lock wait", "command", command,
				"waited_ms", time.Since(started).Milliseconds(), "acquired", lk != nil,
				"budget_ms", updateLockWaitBudget.Milliseconds())
		}
	}()
	staleAttempts := 0
	for {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		lk, err = nodelock.AcquireWithBootID(ctx, e.Layout.Lock, 1, 0, e.Node.BootID.String())
		if err == nil {
			return lk, nil
		}
		if !errors.Is(err, nodelock.ErrBusy) {
			return nil, err
		}
		waited = true
		if lockBusyDetail(err) == "lock" {
			staleAttempts = 0
		} else {
			staleAttempts++
		}
		if staleAttempts == promptLockAttempts {
			return nil, err
		}
		delay := lockRetryInterval
		if staleAttempts == 0 {
			remaining := updateLockWaitBudget - time.Since(started)
			if remaining <= 0 {
				return nil, err
			}
			delay = min(delay, remaining)
		}
		timer := time.NewTimer(delay)
		select {
		case <-ctx.Done():
			timer.Stop()
			return nil, ctx.Err()
		case <-timer.C:
		}
	}
}

package updater

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"math/rand/v2"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/TED-H-com/Freedom-VPN/node/internal/healthattest"
	"github.com/TED-H-com/Freedom-VPN/node/internal/updatejournal"
	"github.com/TED-H-com/Freedom-VPN/node/nodelock"
	"github.com/TED-H-com/Freedom-VPN/node/updater/fsutil"
	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/TED-H-com/Freedom-VPN/pkg/apierr"
	"github.com/TED-H-com/Freedom-VPN/pkg/canonjson"
	"github.com/TED-H-com/Freedom-VPN/pkg/envelope"
	"github.com/google/uuid"
)

// claimed is the job snapshot stored in the journal. Recovery finishes the
// transaction from this snapshot when the control plane is down (§13.6).
type claimed struct {
	Work
	BootID      uuid.UUID `json:"boot_id"`
	StateSchema int       `json:"state_schema"`
	// Source is "installer" for a pending-release apply. Empty is a
	// desired-state job. Installer results carry the same source (D-089).
	Source string `json:"source,omitempty"`
	// PendingPath is the installer record consumed when this job finishes.
	PendingPath   string `json:"pending_path,omitempty"`
	PendingSHA256 string `json:"pending_sha256,omitempty"`
}

// Engine runs one node's update transactions (§13.4 to §13.9).
type Engine struct {
	Layout       Layout
	Node         Node
	Platform     Platform
	ReleaseTrust *envelope.TrustStore
	DesiredTrust *envelope.TrustStore
	// RevokedReleaseIDs is the unsigned release-support list from node config.
	// Installer requests also union the journal's persisted signed revocations.
	RevokedReleaseIDs []uuid.UUID
	Source            Source
	HTTP              *http.Client
	Meter             Meter
	Services          ServiceManager
	Health            HealthChecks
	Gate              Gate
	Migrator          Migrator
	Sender            ResultSink
	Journal           *updatejournal.Journal
	Download          DownloadConfig
	ProbePeer         *healthattest.ChallengeProbe
	// Attest is the challenge window for isolation, DNS and the tunnel probe
	// (D-053). Zero values use HealthAttestWait, HealthAttestPoll and
	// HealthChallengeTTL. The updater config cannot set it.
	Attest        AttestWindow
	Hooks         Hooks
	Now           func() time.Time
	Sleep         func(time.Duration)
	Jitter        func() float64
	FreeBytes     func(path string) (uint64, error)
	AllowLoopback bool
	// AllowedOrigins exempts artifact, manifest and result origins from the
	// private and CGNAT guard (D-046). An entry matches when the scheme, host
	// and effective port are equal. The effective port of a URL or entry
	// without an explicit port is the scheme default: 443 for https and 80
	// for http. Empty keeps the guard. The dial is pinned to that host's
	// resolution.
	AllowedOrigins []string
	Faults         Faults
	Log            *slog.Logger
	// lockHeld is true while this process already owns the update lock.
	// Flush and Retain run from inside Run and must not take it again.
	lockHeld bool
	// bootIDFromConfig is true when the kernel boot id file was unreadable
	// and Node.BootID came from updater.json. It is logged once.
	bootIDFromConfig bool
	bootNoted        bool
	// Probe validation runs afresh under the updater lock for each issuance.
	probeEnv      probeEnvironment
	probeRefusals map[probeRefusal]bool
}

// Close closes the journal when this engine opened it.
func (e *Engine) Close() error {
	if e.Journal == nil {
		return nil
	}
	return e.Journal.Close()
}

// Run applies the current authorized job, resuming a journaled transaction
// first (§13.5). Nil means the local transaction finished or there was no
// work. It does not mean the center has accepted the result.
func (e *Engine) Run(ctx context.Context) error {
	return e.withLockFor(ctx, "run", func() error {
		if err := e.open(ctx); err != nil {
			return err
		}
		blocked := false
		if err := e.Recover(ctx); err != nil {
			if !errors.Is(err, ErrMembersBlocked) {
				return err
			}
			blocked = true
		}
		if err := e.applyPendingLocked(ctx, e.pendingRecordPath(), false); err != nil {
			return err
		}
		for i := 0; i < 8; i++ {
			again, err := e.runOnce(ctx)
			if err != nil {
				return err
			}
			if !again {
				if blocked {
					if on, _ := e.Journal.BlocksForwarding(ctx); on {
						return ErrMembersBlocked
					}
				}
				return nil
			}
			blocked = false
		}
		return permanent(apierr.StaleGeneration, "too many superseded generations")
	})
}

// withLock acquires the node update lock before opening or migrating the
// journal (D-155). AcquireWithBootID creates the lock's parent directory.
// A caller that already holds the lock, such as Flush during seal, runs fn
// directly (D-034d).
func (e *Engine) withLock(ctx context.Context, fn func() error) error {
	return e.withLockFor(ctx, "", fn)
}

// An empty command retains the prompt recovery/library window. The four
// serving-agent commands select D-158's longer contention budget instead.
func (e *Engine) withLockFor(ctx context.Context, command string, fn func() error) error {
	if e.lockHeld {
		e.noteBootFallback()
		return fn()
	}
	var lk *nodelock.Lock
	var err error
	if command == "" {
		lk, err = nodelock.AcquireWithBootID(ctx, e.Layout.Lock, promptLockAttempts, lockRetryInterval, e.Node.BootID.String())
	} else {
		lk, err = e.acquireCommandLock(ctx, command)
	}
	if err != nil {
		if errors.Is(err, nodelock.ErrBusy) {
			return transient(apierr.UpdateBusy, lockBusyDetail(err))
		}
		return err
	}
	defer lk.Release()
	e.lockHeld = true
	defer func() { e.lockHeld = false }()
	e.noteBootFallback()
	return fn()
}

// UseLog sets the engine log and the desired-state reader's log.
func (e *Engine) UseLog(l *slog.Logger) {
	if e == nil {
		return
	}
	if l == nil {
		l = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	e.Log = l
	g, ok := e.Source.(GuardSource)
	if !ok {
		return
	}
	f, ok := g.Inner.(FileSource)
	if !ok {
		return
	}
	f.Log = l
	g.Inner = f
	e.Source = g
}

func (e *Engine) noteBootFallback() {
	if e == nil || !e.bootIDFromConfig || e.bootNoted {
		return
	}
	e.bootNoted = true
	e.log().Info("kernel boot id unreadable; using boot_id from updater config")
}

// Recover finishes an applying or checking transaction before member
// services start (§13.5). ErrMembersBlocked means forwarding stays off.
func (e *Engine) Recover(ctx context.Context) error {
	return e.withLock(ctx, func() error {
		if err := e.open(ctx); err != nil {
			return err
		}
		return e.recoverLocked(ctx)
	})
}

func (e *Engine) recoverLocked(ctx context.Context) error {
	if err := e.cleanInstallerSnapshots(); err != nil {
		return err
	}
	if err := e.consumeFinishedInstallerJobs(ctx); err != nil {
		return err
	}
	txn, err := e.Journal.ActiveTxn(ctx)
	if err == nil {
		if err := e.continueTxn(ctx, txn); err != nil {
			return err
		}
	} else if !errors.Is(err, updatejournal.ErrNotFound) {
		return err
	}
	if err := e.ensureReported(ctx); err != nil {
		return err
	}
	if err := e.holdIfRevoked(ctx); err != nil {
		return err
	}
	on, _ := e.Journal.BlocksForwarding(ctx)
	if on {
		if e.Gate != nil {
			_ = e.Gate.Block(ctx)
		}
		return ErrMembersBlocked
	}
	return e.reapplyPublication(ctx)
}

func (e *Engine) open(context.Context) error {
	if err := e.Layout.Ensure(); err != nil {
		return err
	}
	if e.Journal != nil {
		return nil
	}
	j, err := updatejournal.Open(e.Layout.Journal, updatejournal.Options{Now: e.now})
	if err != nil {
		return err
	}
	e.Journal = j
	return nil
}

func (e *Engine) runOnce(ctx context.Context) (bool, error) {
	if e.Source == nil {
		return false, errors.New("updater: no desired-state source")
	}
	work, err := e.Source.Current(ctx)
	noWork := errors.Is(err, ErrNoWork)
	if err != nil && !noWork {
		return false, err
	}
	// A legacy envelope with no job carries no policy and no signed set.
	// Leave the latch alone, as before.
	if noWork && work.PolicyGeneration == 0 && !work.PolicyKnown && work.SignedRevoked == nil {
		return false, nil
	}
	if err := e.acceptDesired(ctx, &work); err != nil {
		return false, err
	}
	if err := e.rollbackIfRevoked(ctx, e.claimFrom(work)); err != nil {
		return false, err
	}
	if noWork {
		return false, nil
	}
	if err := e.preflight(ctx, work); err != nil {
		return false, err
	}
	if stop, err := e.rejectStale(ctx, work); stop || err != nil {
		return false, err
	}
	if err := e.supersedeOlder(ctx, work); err != nil {
		return false, err
	}
	if !authorized(work, e.now()) {
		return false, transient(apierr.AuthorizationExpired, "update authorization")
	}
	c := e.claimFrom(work)
	raw, err := json.Marshal(c)
	if err != nil {
		return false, err
	}
	stored, _, err := e.Journal.ClaimJob(ctx, updatejournal.Job{
		JobID:          c.Intent.JobId.String(),
		Attempt:        c.Intent.Attempt,
		Generation:     c.Intent.Generation,
		ReleaseID:      c.Intent.ReleaseId.String(),
		ManifestSHA256: strings.ToLower(c.Intent.ManifestSha256),
		IntentJSON:     raw,
	})
	if errors.Is(err, updatejournal.ErrStaleGeneration) {
		return false, permanent(apierr.StaleGeneration, "claim")
	}
	if err != nil {
		return false, err
	}
	if stored.Phase == updatejournal.JobDone {
		return false, nil
	}
	if decoded, err := decodeClaimed(stored.IntentJSON); err == nil {
		c = decoded
	}
	if err := e.hookPhase(ctx, "claimed", c); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageClaim)
	}
	if done, err := e.maybeAlreadyCurrent(ctx, c, stored); done || err != nil {
		return false, err
	}
	if err := e.setPhase(ctx, stored, updatejournal.JobDownloading); err != nil {
		return false, err
	}
	if err := e.hookPhase(ctx, "downloading", c); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageDownload)
	}
	env, manifest, err := e.fetchManifest(ctx, c)
	if err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageDownload)
	}
	if err := e.hookPhase(ctx, "verifying", c); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageVerify)
	}
	if err := e.setPhase(ctx, stored, updatejournal.JobVerifying); err != nil {
		return false, err
	}
	art, err := e.verifyRelease(ctx, c, manifest)
	if err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageVerify)
	}
	path, err := e.fetchArtifact(ctx, c, art)
	if err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageDownload)
	}
	if err := e.hookPhase(ctx, "verified", c); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageVerify)
	}
	if err := e.installTree(ctx, c, manifest, env, art, path); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStageVerify)
	}
	if err := e.setPhase(ctx, stored, updatejournal.JobVerified); err != nil {
		return false, err
	}
	if !authorized(c.Work, e.now()) {
		return false, transient(apierr.AuthorizationExpired, "authorization ended before apply")
	}
	same, err := fsutil.SameFilesystem(e.Layout.Releases, filepath.Dir(e.Layout.Current))
	if err != nil || !same {
		return e.afterPrepareErr(ctx, stored, c, permanent(apierr.StartFailed, "releases and current are not on the same filesystem"), api.UpdateStagePrepare)
	}
	if err := e.catchNewer(ctx, c); err != nil {
		return e.afterPrepareErr(ctx, stored, c, err, api.UpdateStagePrepare)
	}
	if err := e.setPhase(ctx, stored, updatejournal.JobApplying); err != nil {
		return false, err
	}
	txn, err := e.beginOrResume(ctx, c, manifest)
	if err != nil {
		return false, err
	}
	if err := e.continueTxn(ctx, txn); err != nil {
		return false, err
	}
	// A newer generation that arrived while this transaction was applying
	// waits until the transaction is terminal (§13.8), then runs.
	if err := e.catchNewer(ctx, c); errors.Is(err, ErrSuperseded) {
		return true, nil
	}
	return false, nil
}

func (e *Engine) preflight(ctx context.Context, work Work) error {
	if work.Intent.Attempt < 1 {
		return permanent(apierr.SignatureInvalid, "attempt")
	}
	c := e.claimFrom(work)
	if e.Node.Revoked {
		return e.reportUnclaimed(ctx, c, api.UpdateResultStateFailed, api.UpdateStageClaim, apierr.IdentityRevoked)
	}
	if work.Intent.NodeId != e.Node.ID || work.Intent.IncarnationId != e.Node.Incarnation {
		return e.reportUnclaimed(ctx, c, api.UpdateResultStateFailed, api.UpdateStageClaim, apierr.IncarnationMismatch)
	}
	if containsID(work.Revoked, work.Intent.ReleaseId) {
		return e.reportUnclaimed(ctx, c, api.UpdateResultStateFailed, api.UpdateStagePreflight, apierr.ReleaseNotApproved)
	}
	return nil
}

func (e *Engine) rejectStale(ctx context.Context, work Work) (bool, error) {
	gen, _, ok, err := e.Journal.AcceptedGeneration(ctx)
	if err != nil || !ok {
		return false, err
	}
	if work.Intent.Generation >= gen {
		return false, nil
	}
	job, err := e.Journal.GetJob(ctx, work.Intent.JobId.String(), work.Intent.Attempt)
	if err == nil && job.Phase != updatejournal.JobDone {
		c, decErr := decodeClaimed(job.IntentJSON)
		if decErr != nil {
			c = e.claimFrom(work)
		}
		_, ferr := e.finishSupersede(ctx, job, c)
		return true, ferr
	}
	c := e.claimFrom(work)
	return true, e.reportUnclaimed(ctx, c, api.UpdateResultStateSuperseded, api.UpdateStagePreflight, apierr.StaleGeneration)
}

func (e *Engine) supersedeOlder(ctx context.Context, work Work) error {
	open, err := e.Journal.OpenJobs(ctx)
	if err != nil {
		return err
	}
	active, aerr := e.Journal.ActiveTxn(ctx)
	for _, job := range open {
		if aerr == nil && active.JobID == job.JobID && active.Attempt == job.Attempt {
			continue
		}
		if job.JobID == work.Intent.JobId.String() && job.Attempt == work.Intent.Attempt && job.Generation == work.Intent.Generation && strings.EqualFold(job.ManifestSHA256, work.Intent.ManifestSha256) {
			continue
		}
		if job.Generation > work.Intent.Generation {
			continue
		}
		c, err := decodeClaimed(job.IntentJSON)
		if err != nil {
			return err
		}
		if _, err := e.finishSupersede(ctx, job, c); err != nil {
			return err
		}
	}
	return nil
}

func (e *Engine) maybeAlreadyCurrent(ctx context.Context, c claimed, job updatejournal.Job) (bool, error) {
	p, err := e.Journal.Pointers(ctx)
	if err != nil {
		return false, err
	}
	if p.CurrentRelease != c.Intent.ReleaseId.String() {
		return false, nil
	}
	rec, err := e.Journal.GateRecord(ctx)
	if err != nil {
		return false, err
	}
	blocked, _ := e.Journal.BlocksForwarding(ctx)
	// Same release id is not "already current" when the pointers disagree,
	// forwarding is held, or the last terminal outcome failed (D-034b).
	if p.CurrentRelease == "" || p.CurrentRelease != p.LastGood || blocked || terminalBlocksAlready(rec.TerminalOutcome) {
		return false, nil
	}
	if link, _ := e.Layout.currentID(); link != "" && link != p.CurrentRelease {
		return false, nil
	}
	rel, err := e.Journal.GetRelease(ctx, p.CurrentRelease)
	if err != nil {
		return false, nil
	}
	if !strings.EqualFold(rel.ManifestSHA256, c.Intent.ManifestSha256) {
		return false, nil
	}
	manifest, err := VerifyManifest(rel.ManifestEnvelope, rel.ManifestSHA256, e.ReleaseTrust, e.now())
	if err != nil {
		code := apierr.SignatureInvalid
		if op := asOp(err); op != nil {
			code = op.Code
		}
		if berr := e.noteBlocked(ctx, c, updatejournal.OutcomeFailed); berr != nil {
			return true, berr
		}
		return e.failRecorded(ctx, job, c, code, api.UpdateStagePreflight, err)
	}
	schema, _ := e.Journal.StateSchema(ctx)
	if err := checkCompat(manifest, e.Platform, schema, true); err != nil {
		code := apierr.SchemaIncompatible
		if op := asOp(err); op != nil {
			code = op.Code
		}
		if berr := e.noteBlocked(ctx, c, updatejournal.OutcomeFailed); berr != nil {
			return true, berr
		}
		return e.failRecorded(ctx, job, c, code, api.UpdateStagePreflight, err)
	}
	if !containsID(c.Serving, c.Intent.ReleaseId) {
		// The release is already current, but it is not allowed to serve.
		// Record the failure and return it. Do not restart services (§13.9).
		if berr := e.noteBlocked(ctx, c, updatejournal.OutcomeFailed); berr != nil {
			return true, berr
		}
		return e.failRecorded(ctx, job, c, apierr.MinimumVersionViolation, api.UpdateStagePreflight, nil)
	}
	enabled, err := e.enforce(ctx, p.CurrentRelease, c, updatejournal.OutcomeAlreadyCurrent)
	if err != nil {
		return true, err
	}
	in := resultInput{
		Claimed: c, State: api.UpdateResultStateAlreadyCurrent, Stage: api.UpdateStagePreflight,
		Current: p.CurrentRelease, Previous: p.CurrentRelease, Forwarding: enabled,
		Started: job.ClaimedAt, Finished: job.ClaimedAt, Schema: schemaAtLeast1(schema),
	}
	if err := e.enqueueResult(ctx, in); err != nil {
		return true, err
	}
	if err := e.finishInstaller(ctx, c, job, string(api.UpdateResultStateAlreadyCurrent), ""); err != nil {
		return true, err
	}
	return true, nil
}

func terminalBlocksAlready(outcome string) bool {
	switch outcome {
	case updatejournal.OutcomeFailed, updatejournal.OutcomeRolledBack, updatejournal.OutcomeRecoveryRequired:
		return true
	default:
		return false
	}
}

func (e *Engine) noteBlocked(ctx context.Context, c claimed, outcome string) error {
	if e.Journal != nil {
		if err := e.Journal.SetGate(ctx, updatejournal.GateRecord{
			PublicationIntent: string(c.Intent.PublicationIntent),
			ForwardingBlocked: true,
			TerminalOutcome:   outcome,
		}); err != nil {
			return err
		}
	}
	if e.Gate == nil {
		return nil
	}
	if err := e.Gate.Block(ctx); err != nil {
		return wrapCode(apierr.UpdateBusy, err, true)
	}
	return nil
}

func (e *Engine) fetchManifest(ctx context.Context, c claimed) ([]byte, api.ReleaseManifest, error) {
	dest := filepath.Join(e.Layout.Staging, "manifest-"+strings.ToLower(c.Intent.ManifestSha256)+".json")
	poll := func() error { return e.catchNewer(ctx, c) }
	if err := e.download(ctx, c.Intent.ManifestUrl, dest, strings.ToLower(c.Intent.ManifestSha256), hashCanonical, 0, canonjson.MaxBytes, poll); err != nil {
		return nil, api.ReleaseManifest{}, err
	}
	b, err := os.ReadFile(dest)
	if err != nil {
		return nil, api.ReleaseManifest{}, err
	}
	m, err := VerifyManifest(b, c.Intent.ManifestSha256, e.ReleaseTrust, e.now())
	if err != nil {
		_ = os.Remove(dest)
		return nil, api.ReleaseManifest{}, err
	}
	if m.ReleaseId != c.Intent.ReleaseId {
		_ = os.Remove(dest)
		return nil, m, permanent(apierr.SignatureInvalid, "release_id")
	}
	return b, m, nil
}

func (e *Engine) verifyRelease(ctx context.Context, c claimed, m api.ReleaseManifest) (api.ManifestArtifact, error) {
	schema, _ := e.Journal.StateSchema(ctx)
	if schema == 0 {
		schema = e.Platform.StateSchema
	}
	p, _ := e.Journal.Pointers(ctx)
	if err := checkCompat(m, e.Platform, schema, p.CurrentRelease != ""); err != nil {
		return api.ManifestArtifact{}, err
	}
	art, err := selectArtifact(m, e.Platform.OSID, e.Platform.OSVersion, e.Platform.Architecture)
	if err != nil {
		return api.ManifestArtifact{}, err
	}
	if err := checkURLPolicy(art.Url, e.urlPolicy()); err != nil {
		return api.ManifestArtifact{}, err
	}
	need, ok := sumU64(art.SizeBytes.Uint64(), art.InstalledSizeBytes.Uint64(), m.Rollback.RequiredFreeBytes.Uint64())
	if !ok {
		return art, transient(apierr.DiskSpaceLow, "size overflow")
	}
	if err := e.ensureSpace(e.Layout.Releases, need); err != nil {
		return art, err
	}
	if err := e.ensureSpace(e.Layout.Staging, art.SizeBytes.Uint64()); err != nil {
		return art, err
	}
	return art, nil
}

func (e *Engine) fetchArtifact(ctx context.Context, c claimed, art api.ManifestArtifact) (string, error) {
	dest := filepath.Join(e.Layout.Staging, art.Sha256+".tar.zst")
	poll := func() error { return e.catchNewer(ctx, c) }
	if err := e.download(ctx, art.Url, dest, art.Sha256, hashRaw, int64(art.SizeBytes.Uint64()), int64(art.SizeBytes.Uint64()), poll); err != nil {
		return "", err
	}
	st, err := os.Stat(dest)
	if err != nil {
		return "", err
	}
	if err := e.Journal.PutArtifact(ctx, updatejournal.Artifact{
		SHA256: art.Sha256, ReleaseID: c.Intent.ReleaseId.String(), Path: dest, Size: st.Size(),
	}); err != nil {
		return "", err
	}
	return dest, nil
}

func (e *Engine) installTree(ctx context.Context, c claimed, m api.ReleaseManifest, env []byte, art api.ManifestArtifact, artifactPath string) error {
	id := c.Intent.ReleaseId.String()
	dir := e.Layout.releaseDir(id)
	signed, err := e.signedRevokedIDs(ctx)
	if err != nil {
		return err
	}
	if containsID(c.Revoked, c.Intent.ReleaseId) || containsID(signed, c.Intent.ReleaseId) {
		return permanent(apierr.ReleaseNotApproved, "revoked release")
	}
	if rel, err := e.Journal.GetRelease(ctx, id); err == nil {
		sum, herr := fsutil.TreeHash(dir)
		if herr == nil && sum == rel.TreeHash && strings.EqualFold(rel.ManifestSHA256, c.Intent.ManifestSha256) {
			return nil
		}
		return permanent(apierr.SignatureInvalid, "release is immutable")
	}
	p, err := e.Journal.Pointers(ctx)
	if err != nil {
		return err
	}
	if id == p.CurrentRelease || id == p.LastGood {
		return permanent(apierr.SignatureInvalid, "refusing to replace a retained release tree")
	}
	for _, persistent := range e.Layout.PersistentDirs() {
		if pathsOverlap(dir, persistent) {
			return permanent(apierr.ValidationFailed, "release directory overlaps persistent state")
		}
	}
	if err := os.RemoveAll(dir); err != nil {
		return err
	}
	f, err := os.Open(artifactPath)
	if err != nil {
		return err
	}
	defer f.Close()
	// MaxBytes is the installed file-byte cap. ExtractArchive adds tar header
	// overhead on the decompressed stream, so this is not doubled.
	max := int64(art.InstalledSizeBytes.Uint64())
	if max < 1 {
		max = int64(art.SizeBytes.Uint64())
	}
	if max < 1 {
		max = 1 << 20
	}
	err = ExtractArchive(f, dir, ExtractOptions{
		MaxBytes: max, Deny: e.Layout.PersistentDirs(), DiskFull: e.Faults.DiskFullExtract,
	})
	if err != nil {
		_ = os.RemoveAll(dir)
		return err
	}
	if err := fsutil.SyncTree(dir); err != nil {
		_ = os.RemoveAll(dir)
		return err
	}
	sum, err := fsutil.TreeHash(dir)
	if err != nil {
		return err
	}
	return e.Journal.PutRelease(ctx, updatejournal.Release{
		ReleaseID: id, ManifestSHA256: strings.ToLower(c.Intent.ManifestSha256),
		ManifestEnvelope: env, ArtifactSHA256: art.Sha256, TreeHash: sum,
		StateSchemaTo: m.Compatibility.StateSchemaTo,
	})
}

func (e *Engine) beginOrResume(ctx context.Context, c claimed, m api.ReleaseManifest) (updatejournal.Txn, error) {
	if txn, err := e.Journal.ActiveTxn(ctx); err == nil {
		return txn, nil
	} else if !errors.Is(err, updatejournal.ErrNotFound) {
		return updatejournal.Txn{}, err
	}
	p, err := e.Journal.Pointers(ctx)
	if err != nil {
		return updatejournal.Txn{}, err
	}
	schema, err := e.Journal.StateSchema(ctx)
	if err != nil {
		return updatejournal.Txn{}, err
	}
	mig := ""
	if id, err := m.Compatibility.MigrationId.Get(); err == nil {
		mig = id
	}
	id, err := uuid.NewV7()
	if err != nil {
		return updatejournal.Txn{}, err
	}
	from := schema
	if p.CurrentRelease == "" {
		from = 0
	}
	return e.Journal.BeginTxn(ctx, updatejournal.Txn{
		TxnID: id.String(), JobID: c.Intent.JobId.String(), Attempt: c.Intent.Attempt,
		Generation: c.Intent.Generation, ReleaseID: c.Intent.ReleaseId.String(),
		ManifestSHA256:    strings.ToLower(c.Intent.ManifestSha256),
		PreviousReleaseID: p.CurrentRelease, LastGoodReleaseID: p.LastGood,
		StateSchemaFrom: from, StateSchemaTo: m.Compatibility.StateSchemaTo, MigrationID: mig,
	})
}

func (e *Engine) afterPrepareErr(ctx context.Context, job updatejournal.Job, c claimed, err error, stage api.UpdateStage) (bool, error) {
	if errors.Is(err, ErrSuperseded) {
		return e.finishSupersede(ctx, job, c)
	}
	if errors.Is(err, ErrCrashed) || errors.Is(err, context.Canceled) {
		return false, err
	}
	op := asOp(err)
	if op != nil && !op.Retry {
		if ferr := e.failJob(ctx, job, c, op.Code, stage); ferr != nil {
			return false, ferr
		}
		return false, err
	}
	return false, err
}

// failRecorded stores a terminal failure and still returns that failure.
// failJob's nil means the outbox write succeeded, not that the update did.
func (e *Engine) failRecorded(ctx context.Context, job updatejournal.Job, c claimed, code apierr.Code, stage api.UpdateStage, cause error) (bool, error) {
	if ferr := e.failJob(ctx, job, c, code, stage); ferr != nil {
		return true, ferr
	}
	if cause != nil {
		return true, cause
	}
	return true, permanent(code, string(stage))
}

func (e *Engine) failJob(ctx context.Context, job updatejournal.Job, c claimed, code apierr.Code, stage api.UpdateStage) error {
	if c.Intent.JobId == uuid.Nil {
		decoded, err := decodeClaimed(job.IntentJSON)
		if err != nil {
			return err
		}
		c = decoded
	}
	if c.Source == SourceInstaller {
		recorded, err := e.Journal.HasResult(ctx, resultID(job.JobID, job.Attempt, api.UpdateResultStateFailed).String())
		if err != nil {
			return err
		}
		if recorded {
			return e.finishInstaller(ctx, c, job, string(api.UpdateResultStateFailed), string(code))
		}
	}
	p, _ := e.Journal.Pointers(ctx)
	schema, _ := e.Journal.StateSchema(ctx)
	started := job.ClaimedAt
	if started.IsZero() {
		started = c.Intent.IssuedAt
	}
	in := resultInput{
		Claimed: c, State: api.UpdateResultStateFailed, Stage: stage, Code: code,
		Current: p.CurrentRelease, Previous: p.CurrentRelease,
		Started: started, Finished: started, Schema: schemaAtLeast1(schemaOr(schema, e.Platform.StateSchema)),
	}
	if err := e.enqueueResult(ctx, in); err != nil {
		return err
	}
	return e.finishInstaller(ctx, c, job, string(api.UpdateResultStateFailed), string(code))
}

func (e *Engine) reportUnclaimed(ctx context.Context, c claimed, state api.UpdateResultState, stage api.UpdateStage, code apierr.Code) error {
	p, _ := e.Journal.Pointers(ctx)
	schema, _ := e.Journal.StateSchema(ctx)
	started := c.Intent.IssuedAt
	in := resultInput{
		Claimed: c, State: state, Stage: stage, Code: code,
		Current: p.CurrentRelease, Previous: p.CurrentRelease,
		Started: started, Finished: started, Schema: schemaAtLeast1(schemaOr(schema, e.Platform.StateSchema)),
	}
	if err := e.enqueueResult(ctx, in); err != nil {
		return err
	}
	return permanent(code, string(stage))
}

func (e *Engine) finishSupersede(ctx context.Context, job updatejournal.Job, c claimed) (bool, error) {
	if c.Intent.JobId == uuid.Nil {
		decoded, err := decodeClaimed(job.IntentJSON)
		if err != nil {
			return false, err
		}
		c = decoded
	}
	e.discardPartial()
	if _, err := e.Journal.GetRelease(ctx, job.ReleaseID); err != nil {
		p, _ := e.Journal.Pointers(ctx)
		if job.ReleaseID != p.CurrentRelease && job.ReleaseID != p.LastGood {
			_ = os.RemoveAll(e.Layout.releaseDir(job.ReleaseID))
		}
	}
	p, _ := e.Journal.Pointers(ctx)
	schema, _ := e.Journal.StateSchema(ctx)
	started := job.ClaimedAt
	if started.IsZero() {
		started = c.Intent.IssuedAt
	}
	in := resultInput{
		Claimed: c, State: api.UpdateResultStateSuperseded, Stage: api.UpdateStagePreflight,
		Code: apierr.StaleGeneration, Current: p.CurrentRelease, Previous: p.CurrentRelease,
		Started: started, Finished: started, Schema: schemaAtLeast1(schemaOr(schema, e.Platform.StateSchema)),
	}
	if err := e.enqueueResult(ctx, in); err != nil {
		return false, err
	}
	if err := e.finishInstaller(ctx, c, job, string(api.UpdateResultStateSuperseded), string(apierr.StaleGeneration)); err != nil {
		return false, err
	}
	return true, nil
}

func (e *Engine) discardPartial() {
	entries, err := os.ReadDir(e.Layout.Staging)
	if err != nil {
		return
	}
	for _, ent := range entries {
		name := ent.Name()
		if strings.HasSuffix(name, ".partial") || strings.HasSuffix(name, ".partial.meta") {
			_ = os.Remove(filepath.Join(e.Layout.Staging, name))
		}
	}
}

func (e *Engine) ensureReported(ctx context.Context) error {
	txn, err := e.Journal.LastTxn(ctx)
	if errors.Is(err, updatejournal.ErrNotFound) {
		return nil
	}
	if err != nil {
		return err
	}
	if !txn.Stage.Terminal() {
		return nil
	}
	job, err := e.Journal.GetJob(ctx, txn.JobID, txn.Attempt)
	if err != nil {
		return err
	}
	if job.Phase == updatejournal.JobDone {
		return nil
	}
	return e.seal(ctx, txn)
}

func (e *Engine) reapplyPublication(ctx context.Context) error {
	if e.Gate == nil {
		return nil
	}
	rec, err := e.Journal.GateRecord(ctx)
	if err != nil {
		_ = e.Gate.Block(ctx)
		return err
	}
	if !rec.Present {
		return nil
	}
	// failed is the blocking terminal state (there is no StageFailed).
	// recovery_required and an explicit blocked bit stay blocked. A stale
	// transaction is not consulted (D-034b).
	block := rec.ForwardingBlocked || rec.TerminalOutcome == updatejournal.OutcomeRecoveryRequired || rec.TerminalOutcome == updatejournal.OutcomeFailed
	if block || rec.PublicationIntent != string(api.PublicationIntentPublished) {
		if err := e.Gate.Block(ctx); err != nil {
			return wrapCode(apierr.UpdateBusy, err, true)
		}
		return nil
	}
	if err := e.Gate.Unblock(ctx); err != nil {
		return wrapCode(apierr.StartFailed, err, true)
	}
	return nil
}

func (e *Engine) enforce(ctx context.Context, releaseID string, c claimed, outcome string) (bool, error) {
	if e.Gate == nil {
		return false, errors.New("updater: no forwarding gate")
	}
	if outcome == updatejournal.OutcomeRecoveryRequired || outcome == updatejournal.OutcomeFailed {
		if err := e.noteBlocked(ctx, c, outcome); err != nil {
			return false, err
		}
		return false, nil
	}
	signed, err := e.signedRevokedIDs(ctx)
	if err != nil {
		return false, err
	}
	id, _ := uuid.Parse(releaseID)
	// A signed revocation is persisted in the journal. The claim's unsigned
	// list alone must not let that release pass the gate (§13.4).
	allow := c.Source != SourceInstaller && c.Intent.PublicationIntent == api.PublicationIntentPublished &&
		releaseID != "" && containsID(c.Serving, id) && !containsID(c.Revoked, id) && !containsID(signed, id)
	if err := e.Journal.SetGate(ctx, updatejournal.GateRecord{
		PublicationIntent: string(c.Intent.PublicationIntent),
		ForwardingBlocked: !allow,
		TerminalOutcome:   outcome,
	}); err != nil {
		return false, err
	}
	if !allow {
		if err := e.Gate.Block(ctx); err != nil {
			return false, wrapCode(apierr.UpdateBusy, err, true)
		}
		return false, nil
	}
	if err := e.Gate.Unblock(ctx); err != nil {
		return false, wrapCode(apierr.StartFailed, err, true)
	}
	return true, nil
}

func (e *Engine) hookPhase(ctx context.Context, name string, c claimed) error {
	if e.Hooks.AfterPhase != nil {
		if err := e.Hooks.AfterPhase(name); err != nil {
			return err
		}
	}
	return e.catchNewer(ctx, c)
}

func (e *Engine) catchNewer(ctx context.Context, c claimed) error {
	if e.Source == nil {
		return nil
	}
	w, err := e.Source.Current(ctx)
	if err != nil {
		return nil
	}
	if w.Intent.Generation > c.Intent.Generation {
		return ErrSuperseded
	}
	if w.Intent.Generation == c.Intent.Generation &&
		(w.Intent.ReleaseId != c.Intent.ReleaseId || !strings.EqualFold(w.Intent.ManifestSha256, c.Intent.ManifestSha256)) {
		return permanent(apierr.StaleGeneration, "generation reused with different content")
	}
	return nil
}

func (e *Engine) hookStage(stage string) error {
	if e.Hooks.AfterStage == nil {
		return nil
	}
	return e.Hooks.AfterStage(stage)
}

func (e *Engine) setPhase(ctx context.Context, job updatejournal.Job, phase updatejournal.JobPhase) error {
	err := e.Journal.SetJobPhase(ctx, job.JobID, job.Attempt, phase)
	if errors.Is(err, updatejournal.ErrNotFound) {
		return nil
	}
	return err
}

func (e *Engine) finish(ctx context.Context, job updatejournal.Job, outcome, code string) error {
	err := e.Journal.FinishJob(ctx, job.JobID, job.Attempt, outcome, code)
	if errors.Is(err, updatejournal.ErrNotFound) {
		return nil
	}
	return err
}

func (e *Engine) claimFrom(work Work) claimed {
	return claimed{Work: work, BootID: e.Node.BootID, StateSchema: e.Platform.StateSchema}
}

func decodeClaimed(raw []byte) (claimed, error) {
	var c claimed
	err := json.Unmarshal(raw, &c)
	return c, err
}

func authorized(w Work, now time.Time) bool {
	until := w.Intent.AuthorizationValidUntil
	return !until.IsZero() && now.Before(until)
}

func (e *Engine) ensureSpace(path string, need uint64) error {
	free, err := e.freeBytes(path)
	if err != nil {
		return transient(apierr.StoreUnavailable, "free space")
	}
	if free < need {
		return transient(apierr.DiskSpaceLow, "reserve")
	}
	return nil
}

func (e *Engine) freeBytes(path string) (uint64, error) {
	if e.FreeBytes != nil {
		return e.FreeBytes(path)
	}
	return fsutil.FreeBytes(path)
}

func sumU64(parts ...uint64) (uint64, bool) {
	var s uint64
	for _, p := range parts {
		if s+p < s {
			return 0, false
		}
		s += p
	}
	return s, true
}

func schemaOr(a, b int) int {
	if a >= 1 {
		return a
	}
	return b
}

func (e *Engine) log() *slog.Logger {
	if e.Log != nil {
		return e.Log
	}
	return slog.New(slog.NewTextHandler(io.Discard, nil))
}

func (e *Engine) jitter() float64 { return rand.Float64() }

func (e *Engine) urlPolicy() urlPolicy {
	if e == nil {
		return urlPolicy{}
	}
	return urlPolicy{AllowLoopback: e.AllowLoopback, AllowedOrigins: e.AllowedOrigins}
}

func (e *Engine) httpClient() *http.Client {
	return clientWithDial(e.HTTP, e.urlPolicy())
}

// clientWithDial clones base and pins every dial to dialPolicy. The request
// scheme is stored on the dial context so the allowlist matches scheme, host
// and effective port. A transport that is not *http.Transport is left alone;
// the URL check still runs.
func clientWithDial(base *http.Client, policy urlPolicy) *http.Client {
	if base == nil {
		base = http.DefaultClient
	}
	clone := *base
	var tr *http.Transport
	switch t := base.Transport.(type) {
	case *http.Transport:
		tr = t.Clone()
	case nil:
		if def, ok := http.DefaultTransport.(*http.Transport); ok {
			tr = def.Clone()
		}
	}
	if tr != nil {
		tr.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
			return dialPolicy(ctx, network, addr, policy)
		}
		clone.Transport = schemeDialTransport{base: tr}
	}
	inner := base.CheckRedirect
	clone.CheckRedirect = func(req *http.Request, via []*http.Request) error {
		if len(via) >= 3 {
			return errors.New("updater: too many redirects")
		}
		if err := checkURLPolicy(req.URL.String(), policy); err != nil {
			return err
		}
		if inner != nil {
			return inner(req, via)
		}
		return nil
	}
	return &clone
}

// schemeDialTransport records the request scheme for dialPolicy. DialContext
// receives only host:port, and the allowlist matches scheme as well as host
// and effective port (D-046).
type schemeDialTransport struct {
	base http.RoundTripper
}

var _ interface{ CloseIdleConnections() } = schemeDialTransport{}

func (s schemeDialTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	scheme := ""
	if req.URL != nil {
		scheme = req.URL.Scheme
	}
	req = req.WithContext(withDialScheme(req.Context(), scheme))
	return s.base.RoundTrip(req)
}

func (s schemeDialTransport) CloseIdleConnections() {
	type idleCloser interface{ CloseIdleConnections() }
	if c, ok := s.base.(idleCloser); ok {
		c.CloseIdleConnections()
	}
}

// lockBusyDetail keeps a stale-holder reason visible on UPDATE_BUSY. A live
// flock stays "lock". The file is not removed in either case.
func lockBusyDetail(err error) string {
	msg := err.Error()
	if i := strings.LastIndex(msg, ": "); i >= 0 {
		switch msg[i+2:] {
		case "boot id", "pid", "process", "start time":
			return "lock " + msg[i+2:]
		}
	}
	return "lock"
}

func safeURL(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
		return "invalid-url"
	}
	u.RawQuery, u.User = "", nil
	return u.String()
}

func parseUUID(s string) (uuid.UUID, error) { return uuid.Parse(s) }

