// Config is the updater's on-node configuration. It holds paths, never key
// bytes. The release private key is not a field: it lives only on the build
// machine (§16.2). allow_loopback is TEST ONLY.
type Config struct {
	Layout        Layout    `json:"layout"`
	NodeID        uuid.UUID `json:"node_id"`
	IncarnationID uuid.UUID `json:"incarnation_id"`
	// BootID is optional. The kernel boot id is used when
	// /proc/sys/kernel/random/boot_id is readable. This field is the fallback.
	BootID            uuid.UUID `json:"boot_id,omitempty"`
	bootIDFromConfig  bool
	Revoked           bool        `json:"revoked"`
	Platform          Platform    `json:"platform"`
	ReleaseTrust      string      `json:"release_trust"`
	DesiredTrust      string      `json:"desired_trust"`
	DesiredState      string      `json:"desired_state"`
	RevokedReleaseIDs []uuid.UUID `json:"revoked_release_ids"`
	MeterCheckpoint   string      `json:"meter_checkpoint"`
	// MeterCheckpointWaitMS bounds the final-sample handshake. Zero uses 30s.
	MeterCheckpointWaitMS int      `json:"meter_checkpoint_wait_ms,omitempty"`
	StopCommand           []string `json:"stop_command"`
	StartCommand          []string `json:"start_command"`
	// ResultURL is the central /api/v1/agent/update-results endpoint. Empty
	// permits local work but leaves receipts pending; explicit Flush fails.
	ResultURL     string `json:"result_url"`
	MTLSCert      string `json:"mtls_cert"`
	MTLSKey       string `json:"mtls_key"`
	MTLSCA        string `json:"mtls_ca"`
	AllowLoopback bool   `json:"allow_loopback"`
	// AllowedArtifactOrigins exempts listed artifact, manifest and result
	// origins from the private and CGNAT guard (D-046). An entry matches a URL
	// when the scheme, host and effective port are equal. The effective port without
	// an explicit port is the scheme default: 443 for https and 80 for http.
	// Empty keeps the guard. The dev stack sets this explicitly. It does not
	// allow every private address.
	AllowedArtifactOrigins []string `json:"allowed_artifact_origins,omitempty"`
	// ProbePeer names the dedicated synthetic peer and exact sockets for the
	// D-063 health challenge. The agent checks live member/host exclusions.
	ProbePeer *healthattest.ChallengeProbe `json:"probe_peer,omitempty"`
	// AgentConfig supplies control and resolver addresses for probe exclusions.
	// Empty selects /etc/vpn-node/agent.json; only a configured probe reads it.
	AgentConfig  string `json:"agent_config,omitempty"`
	probeSources probeAddressSources
}

// LoadConfig reads a config file. Unknown fields are rejected. Empty layout
// fields fall back to DefaultLayout.
func LoadConfig(path string) (Config, error) {
	return loadConfig(path, probeAddressSources{})
}

func loadConfig(path string, sources probeAddressSources) (Config, error) {
	return loadConfigWithBootFile(path, sources, "/proc/sys/kernel/random/boot_id")
}

func loadConfigWithBootFile(path string, sources probeAddressSources, bootFile string) (Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return Config{}, err
	}
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.DisallowUnknownFields()
	var c Config
	if err := dec.Decode(&c); err != nil {
		return Config{}, errors.New("updater: invalid config JSON")
	}
	if err := dec.Decode(new(any)); err != io.EOF {
		return Config{}, errors.New("updater: invalid config JSON")
	}
	c.probeSources = sources
	if err := c.probeEnvironment().validate(context.Background(), c.ProbePeer); err != nil {
		return Config{}, err
	}
	d := DefaultLayout()
	if c.Layout.Releases == "" {
		c.Layout.Releases = d.Releases
	}
	if c.Layout.Current == "" {
		c.Layout.Current = d.Current
	}
	if c.Layout.Identity == "" {
		c.Layout.Identity = d.Identity
	}
	if c.Layout.State == "" {
		c.Layout.State = d.State
	}
	if c.Layout.Journal == "" {
		c.Layout.Journal = d.Journal
	}
	if c.Layout.Lock == "" {
		c.Layout.Lock = d.Lock
	}
	if c.Layout.Staging == "" {
		c.Layout.Staging = d.Staging
	}
	if c.Layout.Trust == "" {
		c.Layout.Trust = d.Trust
	}
	if c.NodeID == uuid.Nil || c.IncarnationID == uuid.Nil {
		return Config{}, errors.New("updater: node_id and incarnation_id are required")
	}
	boot, fromConfig, err := resolveBootID(c.BootID, bootFile)
	if err != nil {
		return Config{}, err
	}
	c.BootID = boot
	c.bootIDFromConfig = fromConfig
	if c.Platform.OSID == "" || c.Platform.OSVersion == "" || c.Platform.Architecture == "" || c.Platform.UpdaterVersion == "" {
		return Config{}, errors.New("updater: platform is incomplete")
	}
	if c.ReleaseTrust == "" || c.DesiredTrust == "" || c.DesiredState == "" || c.MeterCheckpoint == "" {
		return Config{}, errors.New("updater: release_trust, desired_trust, desired_state and meter_checkpoint are required")
	}
	if _, err := meterWaitDuration(c.MeterCheckpointWaitMS); err != nil {
		return Config{}, err
	}
	if err := validateOrigins(c.AllowedArtifactOrigins); err != nil {
		return Config{}, err
	}
	return c, nil
}

// Engine builds the node engine. Isolation, DNS and the tunnel probe come
// from a challenge-bound attestation in the journal directory (D-053, §13.9).
// Service commands that are empty fail closed at stop.
func (c Config) Engine() (*Engine, error) {
	wait, err := meterWaitDuration(c.MeterCheckpointWaitMS)
	if err != nil {
		return nil, err
	}
	if err := c.probeEnvironment().validate(context.Background(), c.ProbePeer); err != nil {
		return nil, err
	}
	rel, err := readTrust(c.ReleaseTrust)
	if err != nil {
		return nil, err
	}
	desired, err := readTrust(c.DesiredTrust)
	if err != nil {
		return nil, err
	}
	client, err := NewMTLSClient(c.MTLSCert, c.MTLSKey, c.MTLSCA)
	if err != nil {
		return nil, err
	}
	node := Node{ID: c.NodeID, Incarnation: c.IncarnationID, BootID: c.BootID, Revoked: c.Revoked}
	gate := FileGate{Path: filepath.Join(c.Layout.Journal, "forwarding.blocked")}
	origins := append([]string(nil), c.AllowedArtifactOrigins...)
	var sender ResultSink
	if c.ResultURL != "" {
		if err := checkURLPolicy(c.ResultURL, urlPolicy{AllowLoopback: c.AllowLoopback, AllowedOrigins: origins}); err != nil {
			return nil, err
		}
		sender = HTTPSink{URL: c.ResultURL, Client: client, AllowLoopback: c.AllowLoopback, AllowedOrigins: origins}
	}
	return &Engine{
		Layout:       c.Layout,
		Node:         node,
		Platform:     c.Platform,
		ReleaseTrust: rel,
		DesiredTrust: desired,
		Source: GuardSource{
			Inner: FileSource{
				Path: c.DesiredState, Trust: desired, Node: node,
				Revoked: append([]uuid.UUID(nil), c.RevokedReleaseIDs...),
			},
			Gate: gate,
		},
		HTTP:              client,
		Meter:             FileMeter{Path: c.MeterCheckpoint, Wait: wait},
		Services:          CommandServices{StopCmd: c.StopCommand, StartCmd: c.StartCommand},
		Health:            &NodeChecks{Journal: c.Layout.Journal, Node: node, rt: &checkRT{}},
		Gate:              gate,
		Migrator:          noMigrator{},
		Sender:            sender,
		Download:          DefaultDownload(),
		AllowLoopback:     c.AllowLoopback,
		AllowedOrigins:    origins,
		ProbePeer:         cloneProbePeer(c.ProbePeer),
		probeEnv:          c.probeEnvironment(),
		bootIDFromConfig:  c.bootIDFromConfig,
		RevokedReleaseIDs: append([]uuid.UUID(nil), c.RevokedReleaseIDs...),
	}, nil
}

// resolveBootID prefers the kernel boot id. configured is used only when that
// file is missing or not a UUID. fromConfig is true in that fallback.
func resolveBootID(configured uuid.UUID, path string) (id uuid.UUID, fromConfig bool, err error) {
	b, rerr := os.ReadFile(path)
	if rerr == nil {
		parsed, perr := uuid.Parse(strings.TrimSpace(string(b)))
		if perr == nil && parsed != uuid.Nil {
			return parsed, false, nil
		}
	}
	if configured == uuid.Nil {
		return uuid.Nil, false, errors.New("updater: boot_id is required when the kernel boot id is unreadable")
	}
	return configured, true, nil
}

func readTrust(path string) (*envelope.TrustStore, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	ts, err := envelope.ParseNodeTrustStoreJSON(b)
	if err != nil {
		return nil, fmt.Errorf("updater: trust %s: %w", filepath.Base(path), err)
	}
	return ts, nil
}

// ExitBusy identifies live update-lock contention (D-155). Recovery has not
// completed; a caller may defer it and retry after the holder releases the lock.
const ExitBusy = 3

// ExitCode maps an engine error to a process status. 2 means member
// forwarding must stay off (§13.5, §13.9) and takes precedence over ExitBusy.
func ExitCode(err error) int {
	if err == nil {
		return 0
	}
	if errors.Is(err, ErrMembersBlocked) {
		return 2
	}
	var op *OpError
	if errors.As(err, &op) && op.Code == apierr.UpdateBusy && op.Detail == "lock" {
		return ExitBusy
	}
	return 1
}

// FileGate is the stand-in forwarding latch the agent reads before it
// enables member forwarding. The real nftables gate belongs to the agent.
// Block preserves an existing latch; Unblock removes and fsyncs it. Both are
// idempotent. A new latch gets an opaque identity for withdrawal detection.
// D-125 acknowledges this exact identity only after withdrawal/finalization;
// the latch alone is not evidence that the agent has completed its barrier.
type FileGate struct {
	Path string
}

func (g FileGate) Block(context.Context) error {
	if g.Path == "" {
		return errors.New("updater: no forwarding gate")
	}
	if err := os.MkdirAll(filepath.Dir(g.Path), 0o700); err != nil {
		return err
	}
	if _, err := readMeterFile(g.Path); err == nil {
		return nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return fsutil.WriteFileAtomic(g.Path, []byte(uuid.NewString()+"\n"), 0o600)
}

func (g FileGate) Unblock(context.Context) error {
	if g.Path == "" {
		return errors.New("updater: no forwarding gate")
	}
	err := os.Remove(g.Path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	return fsutil.SyncDir(filepath.Dir(g.Path))
}

// Blocked reports whether the latch file is present.
func (g FileGate) Blocked() bool {
	if g.Path == "" {
		return true
	}
	_, err := os.Lstat(g.Path)
	return err == nil
}

// noMigrator refuses a schema change. Config.Engine installs it so a release
// that needs a migration fails before services stop when no migrator was
// supplied (D-034c).
type noMigrator struct{}

func (noMigrator) Migrate(context.Context, int, int, string, string) error {
	return permanent(apierr.MigrationFailed, "no state migrator configured")
}

func (e *Engine) migrationUnsupported() bool {
	if e.Migrator == nil {
		return true
	}
	_, ok := e.Migrator.(noMigrator)
	return ok
}

func (m FileMeter) OpenEpoch(context.Context) (string, error) {
	id, err := uuid.NewV7()
	if err != nil {
		return "", err
	}
	return id.String(), nil
}

// CommandServices runs the configured stop and start commands. An empty
// command fails closed: the updater does not guess systemd. Start appends
// the release directory as the last argument and does not execute anything
// from the manifest (§13.5).
type CommandServices struct {
	StopCmd  []string
	StartCmd []string
}

func (c CommandServices) Stop(ctx context.Context) error {
	return runArgv(ctx, c.StopCmd, nil)
}

func (c CommandServices) Start(ctx context.Context, releaseDir string) error {
	if releaseDir == "" {
		return errors.New("updater: empty release directory")
	}
	return runArgv(ctx, c.StartCmd, []string{releaseDir})
}

func runArgv(ctx context.Context, argv, extra []string) error {
	if len(argv) == 0 || argv[0] == "" {
		return errors.New("updater: service command is not configured")
	}
	args := append(append([]string{}, argv[1:]...), extra...)
	cmd := exec.CommandContext(ctx, argv[0], args...)
	cmd.Stdout = io.Discard
	cmd.Stderr = io.Discard
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("updater: service command failed: %w", err)
	}
	return nil
}

// FileSource reads a desired-state envelope from disk and verifies it on
// every read (§13.4, §14.7). The agent writes the file; the updater does
// not trust it until the signature checks.
type FileSource struct {
	Path    string
	Trust   *envelope.TrustStore
	Node    Node
	Revoked []uuid.UUID
	Now     func() time.Time
	Log     *slog.Logger
}

func (s FileSource) Current(context.Context) (Work, error) {
	b, err := os.ReadFile(s.Path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			// A dangling symlink is an unreadable configured file, not a
			// fresh layout with no desired state.
			if _, statErr := os.Lstat(s.Path); !errors.Is(statErr, os.ErrNotExist) {
				return Work{}, err
			}
			s.logger().Info("desired-state file is absent")
			return Work{}, ErrNoWork
		}
		return Work{}, err
	}
	now := time.Now()
	if s.Now != nil {
		now = s.Now()
	}
	return WorkFromEnvelope(b, s.Trust, s.Node, now, s.Revoked)
}

func (s FileSource) logger() *slog.Logger {
	if s.Log != nil {
		return s.Log
	}
	return slog.Default()
}

// GuardSource turns member forwarding off when the desired state cannot be
// verified. ErrNoWork is not a failure: a valid state with no job leaves
// the latch to the last publication decision (§13.2).
type GuardSource struct {
	Inner Source
	Gate  Gate
}

func (s GuardSource) Current(ctx context.Context) (Work, error) {
	w, err := s.Inner.Current(ctx)
	if err != nil && !errors.Is(err, ErrNoWork) && s.Gate != nil {
		_ = s.Gate.Block(ctx)
	}
	return w, err
}

// WorkFromEnvelope verifies a desired-state envelope and builds the work
// item. revoked is the unsigned release-support list from the agent. A
// present signed revoked_release_ids member, including an empty array, is
// returned in SignedRevoked and does not replace that list. An absent
// member leaves SignedRevoked nil so the caller keeps today's unsigned
// behaviour. PolicyGeneration is the envelope's config_generation (D-043),
// not the update job generation. ErrNoWork still carries that policy and
// any signed revocations so a revoked current release can be stopped
// without an install job.
func WorkFromEnvelope(raw []byte, trust *envelope.TrustStore, node Node, now time.Time, revoked []uuid.UUID) (Work, error) {
	signed, _, err := envelope.Verify(raw, trust, envelope.PurposeDesiredState, now)
	if err != nil {
		if errors.Is(err, envelope.ErrKeyUntrusted) {
			return Work{}, permanent(apierr.KeyUntrusted, "desired state")
		}
		return Work{}, permanent(apierr.SignatureInvalid, "desired state")
	}
	var ds api.DesiredState
	if err := json.Unmarshal(signed, &ds); err != nil {
		return Work{}, permanent(apierr.SignatureInvalid, "desired state")
	}
	if ds.NodeId != node.ID || ds.NodeIncarnationId != node.Incarnation {
		return Work{}, permanent(apierr.IncarnationMismatch, "desired state")
	}
	// Validity is half-open [issued_at, expires_at) (§14.7).
	if now.Before(ds.IssuedAt) || !now.Before(ds.ExpiresAt) {
		return Work{}, permanent(apierr.AuthorizationExpired, "desired state")
	}
	if len(ds.ServingReleaseIds) == 0 {
		return Work{}, permanent(apierr.MinimumVersionViolation, "empty serving set")
	}
	work := Work{
		Serving:          append([]uuid.UUID(nil), ds.ServingReleaseIds...),
		Revoked:          append([]uuid.UUID(nil), revoked...),
		PolicyGeneration: ds.ConfigGeneration,
		PolicyKnown:      true,
	}
	if ds.RevokedReleaseIds != nil {
		ids := append([]uuid.UUID(nil), (*ds.RevokedReleaseIds)...)
		work.SignedRevoked = &ids
	}
	// The disk reader previously treated both omitted and null update as no
	// work. Keep that behavior; central producers must emit the required member.
	if !ds.Update.IsSpecified() || ds.Update.IsNull() {
		work.Intent.PublicationIntent = ds.PublicationIntent
		work.Intent.NodeId = ds.NodeId
		work.Intent.IncarnationId = ds.NodeIncarnationId
		return work, ErrNoWork
	}
	update, _ := ds.Update.Get()
	if update.NodeId != node.ID || update.IncarnationId != node.Incarnation {
		return Work{}, permanent(apierr.IncarnationMismatch, "update intent")
	}
	work.Intent = update
	return work, nil
}

// HTTPSink posts an update result. The contract answers 202. 409 is
// ACK_CONFLICT. Other 4xx responses except 429 are permanent rejections.
// Transport/5xx failures and throttling stay pending (D-062d). Installer
// RESOURCE_NOT_FOUND is retriable until central accepts local evidence (D-089).
type HTTPSink struct {
	Now            func() time.Time // tests may inject the HTTP Retry-After clock
	URL            string
	Client         *http.Client
	AllowLoopback  bool
	AllowedOrigins []string
}

func (s HTTPSink) Submit(ctx context.Context, payload []byte) (Accepted, bool, error) {
	policy := urlPolicy{AllowLoopback: s.AllowLoopback, AllowedOrigins: s.AllowedOrigins}
	if err := checkURLPolicy(s.URL, policy); err != nil {
		return Accepted{}, false, err
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.URL, bytes.NewReader(payload))
	if err != nil {
		return Accepted{}, false, permanent(apierr.ValidationFailed, "result request")
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("User-Agent", "fvpn-updater/"+Version)
	var probe struct {
		ResultID string `json:"result_id"`
	}
	if json.Unmarshal(payload, &probe) == nil {
		if id, err := uuid.Parse(probe.ResultID); err == nil {
			req.Header.Set("Idempotency-Key", id.String())
		}
	}
	resp, err := clientWithDial(s.Client, policy).Do(req)
	if err != nil {
		return Accepted{}, false, transient(apierr.StoreUnavailable, "result submit")
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, (1<<20)+1))
	if err != nil || len(body) > 1<<20 {
		body = nil
	}
	apiCode := responseCode(body)
	switch resp.StatusCode {
	case http.StatusAccepted:
		if err != nil {
			return Accepted{}, false, &DeliveryError{HTTPStatus: resp.StatusCode, Op: transient(apierr.StoreUnavailable, "result response")}
		}
		var ack api.UpdateResultAck
		if err := json.Unmarshal(body, &ack); err != nil {
			return Accepted{}, false, &DeliveryError{HTTPStatus: resp.StatusCode, Op: transient(apierr.ValidationFailed, "result ack")}
		}
		return Accepted{AcceptedAsHistory: ack.AcceptedAsHistory, Raw: append([]byte(nil), body...)}, false, nil
	case http.StatusConflict:
		return Accepted{HTTPStatus: resp.StatusCode, APICode: apiCode, Reason: responseReason(body)}, true, nil
	default:
		code := apierr.Code(apiCode)
		if code == "" || code == apierr.StoreUnavailable {
			code = apierr.ValidationFailed
		}
		retry := false
		var retryAt time.Time
		switch {
		case installerResultPending(payload, resp.StatusCode, apiCode):
			code, retry = apierr.ResourceNotFound, true
		case resp.StatusCode >= 500:
			code, retry = apierr.StoreUnavailable, true
		case resp.StatusCode == http.StatusTooManyRequests:
			code, retry = apierr.RateLimited, true
			now := time.Now()
			if s.Now != nil {
				now = s.Now()
			}
			retryAt = retryAfter(resp.Header.Get("Retry-After"), now)
		case resp.StatusCode < 400:
			code, retry = apierr.ValidationFailed, true
		}
		return Accepted{}, false, &DeliveryError{HTTPStatus: resp.StatusCode, APICode: apiCode, RetryAt: retryAt,
			Op: opErr(code, "result submit", retry)}
	}
}

// NewMTLSClient builds the agent HTTP client. Empty paths mean the default
// system roots and no client certificate. The error text does not include
// file contents.
func NewMTLSClient(certFile, keyFile, caFile string) (*http.Client, error) {
	if certFile == "" && keyFile == "" && caFile == "" {
		return &http.Client{Timeout: 30 * time.Second}, nil
	}
	if (certFile == "") != (keyFile == "") {
		return nil, errors.New("updater: mtls cert and key must both be set")
	}
	cfg := &tls.Config{MinVersion: tls.VersionTLS12}
	if certFile != "" {
		pair, err := tls.LoadX509KeyPair(certFile, keyFile)
		if err != nil {
			return nil, errors.New("updater: mtls certificate")
		}
		cfg.Certificates = []tls.Certificate{pair}
	}
	if caFile != "" {
		b, err := os.ReadFile(caFile)
		if err != nil {
			return nil, errors.New("updater: mtls ca")
		}
		pool := x509.NewCertPool()
		if !pool.AppendCertsFromPEM(b) {
			return nil, errors.New("updater: mtls ca")
		}
		cfg.RootCAs = pool
	}
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: &http.Transport{TLSClientConfig: cfg},
	}, nil
}

// Package nodelock is the node-wide exclusive update lock of §13.5: the agent,
// the manual installer and the updater take the same flock before they change
// the version pointer, the state schema or product services. Contention is
// reported as busy (UPDATE_BUSY), never waited on forever.
package nodelock

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"github.com/google/uuid"
)

// DefaultPath is the default lock file (§4 node paths).
const DefaultPath = "/var/lib/vpn-node/update.lock"

// ErrBusy means another process holds the lock (UPDATE_BUSY, §13.11).
var ErrBusy = errors.New("UPDATE_BUSY: node update lock is held by another process")

// Lock is a held exclusive flock. The descriptor stays open until Release.
type Lock struct {
	f *os.File
}

// holder is the metadata written only after flock succeeds (D-034d).
// StartTime is field 22 of /proc/<pid>/stat, in clock ticks since boot.
type holder struct {
	PID       int    `json:"pid"`
	BootID    string `json:"boot_id"`
	StartTime int64  `json:"start_time"`
}

// TryAcquire takes LOCK_EX|LOCK_NB before it writes holder metadata. It
// returns ErrBusy when the lock is held elsewhere and does not remove the
// file. A crashed holder is released by the kernel when its descriptor
// closes. Stale detection compares the recorded boot id, pid and process
// start time. A stale record does not justify deleting a file another
// process still has locked: the error names the reason and the flock stays.
func TryAcquire(path string) (*Lock, error) {
	return tryAcquire(path, "", "/proc/sys/kernel/random/boot_id")
}

func tryAcquire(path, fallback, bootPath string) (*Lock, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, err
	}
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		if errors.Is(err, syscall.EWOULDBLOCK) {
			h, ok := readHolder(f)
			_ = f.Close()
			if ok {
				if reason, stale := holderStaleReason(h, bootID(bootPath, fallback)); stale {
					// The record is stale, but flock is still held. Do not unlink.
					return nil, fmt.Errorf("%w: %s", ErrBusy, reason)
				}
			}
			return nil, ErrBusy
		}
		_ = f.Close()
		return nil, fmt.Errorf("flock: %w", err)
	}
	if err := writeHolder(f, bootID(bootPath, fallback)); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	return &Lock{f: f}, nil
}

func readBootID() string {
	return bootID("/proc/sys/kernel/random/boot_id", "")
}

func bootID(path, fallback string) string {
	b, err := os.ReadFile(path)
	if err != nil {
		return fallback
	}
	id, err := uuid.Parse(strings.TrimSpace(string(b)))
	if err != nil || id == uuid.Nil {
		return fallback
	}
	return id.String()
}

func readHolder(f *os.File) (holder, bool) {
	st, err := f.Stat()
	if err != nil || st.Size() == 0 || st.Size() > 1<<20 {
		return holder{}, false
	}
	buf := make([]byte, st.Size())
	n, err := f.ReadAt(buf, 0)
	if err != nil || n == 0 {
		return holder{}, false
	}
	var h holder
	if json.Unmarshal(buf[:n], &h) != nil {
		return holder{}, false
	}
	return h, true
}

func writeHolder(f *os.File, boot string) error {
	start, ok := processStartTime(os.Getpid())
	if !ok {
		return errors.New("nodelock: process start time")
	}
	raw, err := json.Marshal(holder{PID: os.Getpid(), BootID: boot, StartTime: start})
	if err != nil {
		return err
	}
	if err := f.Truncate(0); err != nil {
		return err
	}
	if _, err := f.WriteAt(raw, 0); err != nil {
		return err
	}
	return f.Sync()
}

// holderStale reports whether a recorded holder cannot still be this boot's
// live process. A different boot id is stale even when the pid number has
// been reused. A dead pid is stale on the same boot. The same pid is stale
// when its /proc start time differs, which is how a reused pid is told apart
// from the process that took the lock.
func holderStale(h holder, boot string) bool {
	_, stale := holderStaleReason(h, boot)
	return stale
}

// holderStaleReason names why a record is stale: "boot id", "pid",
// "process" or "start time". A live flock holder is not stale.
func holderStaleReason(h holder, boot string) (string, bool) {
	if h.BootID != boot {
		return "boot id", true
	}
	if h.PID <= 0 {
		return "pid", true
	}
	if syscall.Kill(h.PID, 0) != nil {
		return "process", true
	}
	start, ok := processStartTime(h.PID)
	if !ok {
		return "process", true
	}
	if h.StartTime == 0 || h.StartTime != start {
		return "start time", true
	}
	return "", false
}

// processStartTime reads field 22 of /proc/<pid>/stat (starttime, clock ticks
// since boot). The command name is in parentheses and may itself contain
// spaces and parentheses, so the fields are counted after the last ')'.
func processStartTime(pid int) (int64, bool) {
	b, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	if err != nil {
		return 0, false
	}
	return parseStatStart(string(b))
}

func parseStatStart(s string) (int64, bool) {
	i := strings.LastIndex(s, ")")
	if i < 0 || i+2 >= len(s) {
		return 0, false
	}
	fields := strings.Fields(s[i+2:])
	// Field 22 is index 19 of the fields that follow the command name.
	if len(fields) <= 19 {
		return 0, false
	}
	n, err := strconv.ParseInt(fields[19], 10, 64)
	if err != nil || n <= 0 {
		return 0, false
	}
	return n, true
}

// Acquire retries TryAcquire with a fixed interval until attempts run out or
// ctx ends (bounded wait, §13.11 UPDATE_BUSY).
func Acquire(ctx context.Context, path string, attempts int, interval time.Duration) (*Lock, error) {
	return AcquireWithBootID(ctx, path, attempts, interval, "")
}

// AcquireWithBootID uses fallback only if the kernel boot id is unreadable.
// It otherwise has the same bounded contention behavior as Acquire.
func AcquireWithBootID(ctx context.Context, path string, attempts int, interval time.Duration, fallback string) (*Lock, error) {
	if attempts < 1 {
		attempts = 1
	}
	var last error
	for i := 0; i < attempts; i++ {
		l, err := tryAcquire(path, fallback, "/proc/sys/kernel/random/boot_id")
		if err == nil {
			return l, nil
		}
		last = err
		if !errors.Is(err, ErrBusy) {
			return nil, err
		}
		if i == attempts-1 {
			break
		}
		t := time.NewTimer(interval)
		select {
		case <-ctx.Done():
			t.Stop()
			return nil, ctx.Err()
		case <-t.C:
		}
	}
	return nil, last
}

// Release drops the lock. It is safe to call more than once.
func (l *Lock) Release() error {
	if l == nil || l.f == nil {
		return nil
	}
	err := syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
	cerr := l.f.Close()
	l.f = nil
	if err != nil {
		return err
	}
	return cerr
}

// Command fvpn-e2e-prepare writes one run of dev-stack secrets and config.
// Output stays in the git-ignored state directory. It does not reuse TEST ONLY
// fixture keys (D-039, D-045) and it never prints secret material.
package main

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"encoding/pem"
	"flag"
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/TED-H-com/Freedom-VPN/internal/config"
	"github.com/TED-H-com/Freedom-VPN/internal/pki"
	"github.com/TED-H-com/Freedom-VPN/internal/signing"
	"github.com/TED-H-com/Freedom-VPN/packaging/release"
	"github.com/TED-H-com/Freedom-VPN/pkg/envelope"
	"github.com/TED-H-com/Freedom-VPN/tests/e2e/internal/labtls"
	"golang.org/x/crypto/bcrypt"
)

func main() {
	state := flag.String("state", "", "git-ignored state directory")
	reset := flag.Bool("reset", false, "replace an existing state directory")
	prefix := flag.String("prefix", "e2e", "short stack prefix")
	portBase := flag.Int("port-base", 18000, "loopback port base")
	graceSeconds := flag.Int("grace-seconds", 0, "TEST ONLY payment grace seconds (0 disables grace; prepare-time setting)")
	twoResolvers := flag.Bool("two-resolvers", false, "TEST ONLY publish two controlled resolver addresses")
	flag.Parse()
	if *state == "" {
		fmt.Fprintln(os.Stderr, "fvpn-e2e-prepare: -state is required")
		os.Exit(2)
	}
	lay, err := parseLayout(*prefix, *portBase)
	if err != nil {
		fmt.Fprintf(os.Stderr, "fvpn-e2e-prepare: %s\n", err.Error())
		os.Exit(2)
	}
	if err := run(*state, *reset, lay, *graceSeconds, *twoResolvers); err != nil {
		fmt.Fprintf(os.Stderr, "fvpn-e2e-prepare: failed: %s\n", err.Error())
		os.Exit(1)
	}
	fmt.Println("e2e state ready")
}

func run(state string, reset bool, lay layout, graceSeconds int, twoResolvers ...bool) error {
	if graceSeconds < 0 || graceSeconds > 366*24*60*60 {
		return fmt.Errorf("grace-seconds must be 0..31622400")
	}
	graceReason := ""
	if graceSeconds > 0 {
		graceReason = "TEST ONLY finite payment grace"
	}
	marker := filepath.Join(state, "ready")
	if !reset {
		if _, err := os.Stat(marker); err == nil {
			return nil
		}
	}
	if err := os.RemoveAll(state); err != nil {
		return err
	}
	if err := os.MkdirAll(state, 0o700); err != nil {
		return err
	}
	now := time.Now().UTC().Truncate(time.Second)
	notBefore := now.Add(-5 * time.Minute)
	notAfter := now.Add(72 * time.Hour)

	ca, err := labtls.NewAuthority("e2e-lab", notBefore, notAfter)
	if err != nil {
		return err
	}
	if err := writeSecret(filepath.Join(state, "ca.pem"), ca.CertPEM); err != nil {
		return err
	}
	if err := writeSecret(filepath.Join(state, "ca.key"), ca.KeyPEM); err != nil {
		return err
	}
	certs := []struct {
		name string
		dns  []string
		ips  []net.IP
	}{
		{"fault-proxy", []string{"localhost"}, []net.IP{net.ParseIP("127.0.0.1")}},
		{"control", []string{"portal.example.invalid", "agent.example.invalid"}, nil},
		{"idp", []string{"idp.example.invalid"}, nil},
		{"payment", []string{"api.stripe.com"}, nil},
		{"origin", []string{"releases.example.invalid"}, []net.IP{net.ParseIP(lay.OriginIP)}},
		{"netbird", []string{"netbird.example.invalid"}, nil},
	}
	for _, item := range certs {
		certPEM, keyPEM, err := labtls.ServerCert(ca, item.dns[0], item.dns, item.ips, notBefore, notAfter)
		if err != nil {
			return err
		}
		dir := filepath.Join(state, "certs")
		if err := writeSecret(filepath.Join(dir, item.name+".crt"), certPEM); err != nil {
			return err
		}
		if err := writeSecret(filepath.Join(dir, item.name+".key"), keyPEM); err != nil {
			return err
		}
		if item.name == "fault-proxy" {
			if err := writeSecret(filepath.Join(state, "node", "etc", "fault-proxy.crt"), certPEM); err != nil {
				return err
			}
			if err := writeSecret(filepath.Join(state, "node", "etc", "fault-proxy.key"), keyPEM); err != nil {
				return err
			}
		}
		if item.name == "control" {
			// The secrets directory is one read-only mount. A second mount of
			// these files inside that directory cannot create its mountpoint.
			if err := writeSecret(filepath.Join(state, "secrets", "tls.crt"), certPEM); err != nil {
				return err
			}
			if err := writeSecret(filepath.Join(state, "secrets", "tls.key"), keyPEM); err != nil {
				return err
			}
		}
	}

	password, err := randomHex(24)
	if err != nil {
		return err
	}
	if err := writeSecret(filepath.Join(state, "secrets", "postgres.password"), []byte(password)); err != nil {
		return err
	}
	dsn := "postgres://fvpn:" + password + "@postgres:5432/fvpn?sslmode=disable\n"
	if err := writeSecret(filepath.Join(state, "secrets", "database.url"), []byte(dsn)); err != nil {
		return err
	}
	secrets := map[string]int{
		"oidc.secret":    32,
		"stripe.key":     32,
		"payment.secret": 32,
		"webhook.secret": 32,
		"assume.secret":  32,
		"origin.secret":  32,
	}
	for name, n := range secrets {
		raw, err := randomHex(n)
		if err != nil {
			return err
		}
		if err := writeSecret(filepath.Join(state, "secrets", name), []byte(raw+"\n")); err != nil {
			return err
		}
	}
	vaultKey := make([]byte, 32)
	if _, err := rand.Read(vaultKey); err != nil {
		return err
	}
	if err := writeSecret(filepath.Join(state, "secrets", "vault.key"), vaultKey); err != nil {
		return err
	}
	// Non-empty until NetBird bootstrap replaces it. Control refuses an empty file.
	if err := writeSecret(filepath.Join(state, "secrets", "netbird.token"), []byte("pending-netbird-bootstrap\n")); err != nil {
		return err
	}

	ctx := context.Background()
	vaultDir := filepath.Join(state, "vault")
	vault, err := signing.InitializeFileProvider(vaultDir)
	if err != nil {
		return err
	}
	caKeyID, err := vault.Rotate(ctx, signing.NodeCA, 72*time.Hour, time.Hour)
	if err != nil {
		return err
	}
	for _, purpose := range []signing.Purpose{signing.BootstrapSecret, signing.DesiredState, signing.Lease, signing.Recovery, signing.LedgerEpoch} {
		if _, err := vault.Rotate(ctx, purpose, 72*time.Hour, time.Hour); err != nil {
			return err
		}
	}
	der, err := pki.CreateDevCA(ctx, vault, caKeyID, 72*time.Hour)
	if err != nil {
		return err
	}
	agentCA := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
	if err := writeSecret(filepath.Join(state, "node", "etc", "agent-ca.pem"), agentCA); err != nil {
		return err
	}
