func writeAdGuard(state, coreDNS string, rrMatrix ...bool) error {
	password, err := randomHex(16)
	if err != nil {
		return err
	}
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.MinCost)
	if err != nil {
		return err
	}
	if err := writeSecret(filepath.Join(state, "secrets", "adguard.password"), []byte(password+"\n")); err != nil {
		return err
	}
	if err := writeJSON(filepath.Join(state, "node", "etc", "resolver-credentials.json"), map[string]string{"username": "e2e", "password": password}); err != nil {
		return err
	}
	// schema_version 29 is what v0.107.59 writes. A lower version runs the
	// upgrader, which nested bootstrap_dns into a sequence of sequences and
	// then refused to parse it. Query log stays off (SEC02).
	body := fmt.Sprintf(`# Generated per run. schema_version 29; query log is off (SEC02).
auth_attempts: 5
block_auth_min: 15
clients:
  persistent: []
  runtime_sources:
    arp: true
    dhcp: true
    hosts: true
    rdns: false
    whois: true
dhcp:
  dhcpv4: {}
  enabled: false
dns:
  aaaa_disabled: true
  allowed_clients:
    - 127.0.0.0/8
    - 172.16.0.0/12
    - 10.0.0.0/8
    - 192.168.0.0/16
    - 100.64.0.0/10
  anonymize_client_ip: true
  bind_hosts:
    - 0.0.0.0
  bootstrap_dns:
    - %s:53
  # TEST ONLY: keep the historical 4 KiB fixture override; pin default is 4 MiB.
  cache_size: 4096
  cache_ttl_max: 0
  cache_ttl_min: 0
  edns_client_subnet:
    custom_ip: ""
    enabled: false
    use_custom: false
  enable_dnssec: false
  hostsfile_enabled: false
  port: 53
  ratelimit: 0
  refuse_any: true
  serve_plain_dns: true
  upstream_dns:
    - %s:53
  upstream_mode: load_balance
filtering:
  blocked_services:
    schedule:
      time_zone: Local
  safe_fs_patterns:
    - /opt/adguardhome/work/data/userfilters/*
  safe_search:
    bing: false
    duckduckgo: false
    enabled: false
    google: false
    pixabay: false
    yandex: false
    youtube: false
filters: []
http:
  address: 127.0.0.1:8080
  pprof:
    enabled: false
    port: 6060
  session_ttl: 720h
os:
  group: ""
  rlimit_nofile: 0
  user: ""
querylog:
  enabled: false
  file_enabled: false
  ignored: []
  interval: 2160h
  size_memory: 1000
schema_version: 29
statistics:
  enabled: false
  ignored: []
  interval: 24h
user_rules: []
users:
  - name: e2e
    password: %q
whitelist_filters: []
`, coreDNS, coreDNS, string(hash))
	if len(rrMatrix) > 0 && rrMatrix[0] {
		body = strings.Replace(body, "aaaa_disabled: true", "aaaa_disabled: false", 1)
	}
	dir := filepath.Join(state, "adguard", "conf")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "AdGuardHome.yaml"), []byte(body), 0o600)
}

func cloneMap(in map[string]any) map[string]any {
	out := make(map[string]any, len(in)+1)
	for k, v := range in {
		out[k] = v
	}
	return out
}

func writeJSON(path string, v any) error {
	raw, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return err
	}
	raw = append(raw, '\n')
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	return os.WriteFile(path, raw, 0o600)
}

func writeSecret(path string, body []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	return os.WriteFile(path, body, 0o600)
}

func randomHex(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

//go:build e2e

package e2e

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/TED-H-com/Freedom-VPN/pkg/api"
	"github.com/TED-H-com/Freedom-VPN/pkg/canonjson"
)

// BuildInstallerRelease shares the lab's release signer and builds real Linux
// amd64/arm64 binaries at the installer layout, with unchanged packaged units.
// RegisterRelease performs public registration and worker verification readback.
func (s *Stack) BuildInstallerRelease(ctx context.Context, dir, version, sequence, build string, options ReleaseOptions) (BuiltRelease, error) {
	options.InstallerLayout = true
	b, err := s.BuildRelease(ctx, dir, version, sequence, build, options)
	if err == nil {
		err = os.WriteFile(filepath.Join(dir, "manifest.json"), b.Manifest, 0600)
	}
	return b, err
}

// RegisterInstallerReleases registers PrepareInstallerNode's older/newer real
// bundles. Activate a release_support policy including their IDs separately;
// registration alone is not permission to serve or a healthy update outcome.
func (s *Stack) RegisterInstallerReleases(ctx context.Context, admin BrowserSession) ([]BuiltRelease, error) {
	var result []BuiltRelease
	for _, which := range []string{"older", "newer"} {
		dir := filepath.Join(s.lab.root, ".agent", "tmp", "e2e-installer-rel", which)
		raw, err := os.ReadFile(filepath.Join(dir, "manifest.json"))
		if err != nil {
			return result, err
		}
		var envelope struct{ Signed api.ReleaseManifest }
		if err = json.Unmarshal(raw, &envelope); err != nil {
			return result, err
		}
		hash, err := canonjson.HashHex(raw)
		if err != nil {
			return result, err
		}
		b := BuiltRelease{ID: envelope.Signed.ReleaseId, Directory: dir, Manifest: raw, ManifestSHA256: hash}
		if err = s.RegisterRelease(ctx, admin, b); err != nil {
			return result, err
		}
		result = append(result, b)
	}
	return result, nil
}

// Start AdGuard before the first NetBird join, as in the ordinary node topology.
// Otherwise NetBird's unused DNS stub can occupy the overlay port 53 first.
func (s *Stack) prepareInstallerResolver(ctx context.Context) error {
	c := s.installerContainer()
	base := filepath.Join(s.lab.state, "installer-node", "adguard")
	for _, dir := range []string{"conf", "work"} {
		if err := os.MkdirAll(filepath.Join(base, dir), 0700); err != nil {
			return err
		}
	}
	name := c + "-adguard"
	if exec.CommandContext(ctx, "docker", "inspect", name).Run() != nil {
		if err := dockerCopy(ctx, s.lab.prefix+"-adguard:/opt/adguardhome/conf/AdGuardHome.yaml", filepath.Join(base, "conf", "AdGuardHome.yaml")); err != nil {
			return err
		}
		img, err := exec.CommandContext(ctx, "docker", "inspect", "--format={{.Image}}", s.lab.prefix+"-adguard").Output()
		if err != nil {
			return err
		}
		if err = exec.CommandContext(ctx, "docker", "run", "-d", "--name", name, "--network", "container:"+c,
			"--mount", "type=bind,src="+filepath.Join(base, "conf")+",dst=/opt/adguardhome/conf",
			"--mount", "type=bind,src="+filepath.Join(base, "work")+",dst=/opt/adguardhome/work",
			strings.TrimSpace(string(img)), "--no-check-update", "--no-permcheck", "-c", "/opt/adguardhome/conf/AdGuardHome.yaml", "-w", "/opt/adguardhome/work").Run(); err != nil {
			return err
		}
	}
	ready, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	if !waitUntil(ready, 200*time.Millisecond, func() bool {
		raw, err := exec.CommandContext(ready, "docker", "exec", c, "ss", "-H", "-lnu", "sport = :53").Output()
		return err == nil && strings.Contains(string(raw), ":53")
	}) {
		return fmt.Errorf("installer resolver did not bind DNS before NetBird startup")
	}
	return nil
}

// ConfigureInstallerServing supplies the real AdGuard backend missing from the
// installer's minimal configuration. The generated agent.json is preserved;
// a TEST ONLY runtime drop-in selects agent-lab.json, copied from it with DNS
// and short observation intervals. Call again after reenrollment/release change.
// This does not publish an exit, grant a member, or write observations.
func (s *Stack) ConfigureInstallerServing(ctx context.Context) error {
	c := s.installerContainer()
	if err := copyPrivateContainerFile(ctx, s.lab.prefix+"-node", "/etc/vpn-node/resolver-credentials.json", c, "/etc/vpn-node/resolver-credentials.json"); err != nil {
		return err
	}
	if err := exec.CommandContext(ctx, "docker", "exec", c, "sh", "-c", "chown 0:0 /etc/vpn-node/resolver-credentials.json && chmod 600 /etc/vpn-node/resolver-credentials.json").Run(); err != nil {
		return err
	}
	raw, err := exec.CommandContext(ctx, "docker", "exec", c, "cat", "/etc/vpn-node/agent.json").Output()
	if err != nil {
		return err
	}
	var cfg map[string]any
	if err = json.Unmarshal(raw, &cfg); err != nil {
		return err
	}
	cfg["dns"] = map[string]any{"resolvers": []any{map[string]string{"id": "lab", "admin_url": "http://127.0.0.1:8080", "dns_addr": "127.0.0.1:53"}}, "resolver_credentials_file": "/etc/vpn-node/resolver-credentials.json"}
	cfg["test_mode"] = true
	cfg["heartbeat_seconds"], cfg["poll_seconds"], cfg["observation_seconds"] = 5, 5, 5
	raw, err = json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return err
	}
	if err = writeContainerFile(ctx, c, "/etc/vpn-node/agent-lab.json", "644", raw); err != nil {
		return err
	}
	for _, unit := range []string{"agent", "watchdog"} {
		body := fmt.Sprintf("[Service]\nExecStart=\nExecStart=/opt/vpn-node/current/fvpn-%s run -config /etc/vpn-node/agent-lab.json\n", unit)
		if err = writeContainerFile(ctx, c, "/run/systemd/system/fvpn-"+unit+".service.d/e2e-serving.conf", "644", []byte(body)); err != nil {
			return err
		}
	}
	return exec.CommandContext(ctx, "docker", "exec", c, "systemctl", "daemon-reload").Run()
}

// The source is root-owned mode 0600 after the ordinary node entrypoint. Pipe
// directly between owned containers; do not read the private host bind mount or
// expose credential bytes in command arguments, diagnostics or evidence.
func copyPrivateContainerFile(ctx context.Context, source, sourcePath, target, targetPath string) error {
	read := exec.CommandContext(ctx, "docker", "exec", source, "cat", "--", sourcePath)
	write := exec.CommandContext(ctx, "docker", "exec", "-i", target, "sh", "-c", `umask 077; cat > "$1" && chmod 600 "$1"`, "sh", targetPath)
	pipe, err := read.StdoutPipe()
	if err != nil {
		return err
	}
	write.Stdin = pipe
	if err = read.Start(); err != nil {
		return err
	}
	writeErr := write.Run()
	_ = pipe.Close()
	readErr := read.Wait()
	if writeErr != nil || readErr != nil {
		return fmt.Errorf("private container file transfer failed")
	}
	return nil
}

